-- GENERATED by scripts/gen-sheetslab7-sql.mjs from src/lessons/sheetsLab7: edit the TypeScript, then regenerate.
-- Needs 041_sheet_criteria.sql. Idempotent: the course is found by title, the module by title, lessons by module position (or title).

do $informatics7$
declare
  v_school uuid; v_owner uuid; v_course uuid; v_module uuid; v_lesson uuid; v_spec record;
begin
  -- the course belongs to the teacher who owns the 8th-grade course (so it shows in that teacher's library)
  select c.owner_id, c.school_id into v_owner, v_school from public.cf_curr_courses c
  where c.title in ('Informatics 8th grade', 'Информатика 8-сынып', 'Информатика 8') order by c.created_at limit 1;
  if v_owner is null then select p.id, p.school_id into v_owner, v_school from public.profiles p where p.role in ('teacher', 'admin') order by p.created_at limit 1; end if;
  if v_owner is null then raise exception 'Мұғалім немесе әкімші аккаунты табылмады'; end if;

  select id into v_course from public.cf_curr_courses where title = $s7$Informatics 7th grade$s7$ and school_id = v_school limit 1;
  if v_course is null then
    insert into public.cf_curr_courses (school_id, owner_id, title, subject, grade)
    values (v_school, v_owner, $s7$Informatics 7th grade$s7$, $s7$Информатика$s7$, 7) returning id into v_course;
  end if;

  select id into v_module from public.cf_curr_modules where course_id = v_course and title = $s7$Электрондық кестелер (3-тарау)$s7$ limit 1;
  if v_module is null then
    insert into public.cf_curr_modules (course_id, title, position, kind, quarter, grade)
    values (v_course, $s7$Электрондық кестелер (3-тарау)$s7$, 0, 'lesson', 2, 7) returning id into v_module;
  end if;

  for v_spec in select * from (values
    ($s7$3.1 Мәтіндік редактордағы кестелер$s7$, $s7$Информатика$s7$, 0, $s7${"summary":"Кесте — жолдар мен бағандардан тұратын құрылым. Google Docs-та кесте қою, өлшемін өзгерту және пішімдеу.","objectives":["Кестенің жолдары мен бағандарын ажырату","Мәтіндік редакторға берілген өлшемді кесте қою","Кесте элементтерін пішімдеу: қаріп, түс, туралау, шекара"],"grade":7,"duration":"45 минут","prior":"Мәтіндік құжатты ашып, мәтін теріп, сақтай алады.","env":"Кесте: ClassFlow кестесі немесе Google Sheets. Google Docs/Sheets үшін оқушыда Google аккаунты және интернет болуы керек (аккаунт мектеп ережесіне сай ашылады). Әр оқушыға бір құрылғы.","source":"A. Zhunussov, Ye. Shaniyev, I. Gesen. Informatics, Grade 7, 1st ed., Almaty, 2021, 26–27 беттер. Сабақтағы формулалар мен жауаптар кестеде орындалып тексерілген, деректер ойдан шығарылған.","stages":[{"k":"warmup","min":5,"do":"Кесте және құпия сөз туралы екі сұраққа жауап береді"},{"k":"together","min":8,"do":"Кестенің не екенін және Google Docs-та қалай қойылатынын біледі"},{"k":"example","min":10,"do":"Мұғаліммен бірге «Сабақ кестесін» пішімдеу қадамдарын орындайды"},{"k":"practice","min":15,"do":"Google Docs-та өз сабақ кестесін жасап, екі есеп шығарады"},{"k":"check","min":7,"do":"Қысқа тест тапсырып, не үйренгенін айтады"}],"ru":{"summary":"Таблица — структура из строк и столбцов. Вставка, изменение размера и форматирование таблицы в Google Docs.","objectives":["Различать строки и столбцы таблицы","Вставлять в текстовый редактор таблицу заданного размера","Форматировать элементы таблицы: шрифт, цвет, выравнивание, границы"],"prior":"Умеют открыть текстовый документ, набрать текст и сохранить.","env":"Таблица: ClassFlow или Google Sheets. Для Google Docs/Sheets нужны аккаунт Google и интернет (аккаунт — по правилам школы). Каждому ученику по устройству.","source":"A. Zhunussov, Ye. Shaniyev, I. Gesen. Informatics, Grade 7, 1st ed., Almaty, 2021, с. 26–27. Формулы и ответы урока проверены выполнением в таблице, данные вымышленные.","stages":["Отвечает на два вопроса о таблице и пароле","Узнаёт, что такое таблица и как вставить её в Google Docs","Вместе с учителем проходит шаги форматирования «Расписания»","Делает своё расписание в Google Docs и решает две задачи","Проходит короткий тест и говорит, что узнал"]},"en":{"summary":"A table is a structure of rows and columns. Inserting, resizing and formatting a table in Google Docs.","objectives":["Tell the rows and the columns of a table apart","Insert a table of a given size into a word processor","Format table elements: font, colour, alignment, borders"],"prior":"Can open a text document, type text and save it.","env":"Spreadsheet: the ClassFlow sheet or Google Sheets. Google Docs/Sheets need a Google account and the internet (the account follows the school rules). One device per student.","source":"A. Zhunussov, Ye. Shaniyev, I. Gesen. Informatics, Grade 7, 1st ed., Almaty, 2021, pp. 26–27. The formulas and answers of the lesson were run in a sheet; the data are made up.","stages":["Answers two questions about tables and passwords","Learns what a table is and how to insert it in Google Docs","Follows the formatting steps of the lesson schedule with the teacher","Builds the own lesson schedule in Google Docs and solves two problems","Takes a short test and says what was learned"]}}$s7$::jsonb, $s7$[{"term":"table","definition":"Кесте — жолдар мен бағандардан тұратын жиынтық · Таблица — набор строк и столбцов · Table — a set of rows and columns"},{"term":"cell","definition":"Ұяшық — жол мен бағанның қиылысы · Ячейка — пересечение строки и столбца · Cell — where a row and a column meet"},{"term":"landscape","definition":"Көлденең бет бағыты (альбомная) · Альбомная ориентация страницы · Landscape — the page is wider than it is tall"}]$s7$::jsonb, $s7$[{"type":"title","pageType":"slide","templateId":"title","title":"3.1 Мәтіндік редактордағы кестелер","subtitle":"Информатика 7-сынып · 3-тарау · оқулық 26–27-б.","ru":{"title":"3.1 Таблицы в текстовом редакторе","subtitle":"Информатика 7 класс · глава 3 · учебник, с. 26–27"},"en":{"title":"3.1 Tables in a word processor","subtitle":"Informatics Grade 7 · Chapter 3 · textbook pp. 26–27"},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: кесте","prompt":"Кесте неден тұрады?","options":["Жолдар мен бағандардан","Тек бағандардан","Тек суреттерден","Тек сөйлемдерден"],"answer":0,"explanation":"Кесте — жолдар (көлденең) мен бағандардың (тік) жиынтығы.","points":1,"ru":{"title":"Повторение: таблица","prompt":"Из чего состоит таблица?","options":["Из строк и столбцов","Только из столбцов","Только из рисунков","Только из предложений"],"explanation":"Таблица — набор строк (горизонтально) и столбцов (вертикально).","notes":"5 минут. Ответы с телефона. Примеры таблиц: расписание, дневник."},"en":{"title":"Review: tables","prompt":"What is a table made of?","options":["Rows and columns","Columns only","Pictures only","Sentences only"],"explanation":"A table is a set of rows (horizontal) and columns (vertical).","notes":"5 minutes. Answers from phones. Table examples: the timetable, the gradebook."},"stage":"warmup","notes":"5 минут. Жауаптарды телефоннан жіберіңдер. Кесте мысалы: сабақ кестесі, күнделік."},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: құпия сөз","prompt":"Google аккаунтына қандай құпия сөз қою дұрыс?","options":["Ұзын, болжау қиын: әріптер, сандар, таңбалар","Өз атың","12345","Туған күнің"],"answer":0,"explanation":"Күшті құпия сөз ұзын және болжау қиын болады. Оны ешкімге айтпа.","points":1,"ru":{"title":"Повторение: пароль","prompt":"Какой пароль правильно ставить на аккаунт Google?","options":["Длинный, трудно угадать: буквы, цифры, знаки","Своё имя","12345","Дата рождения"],"explanation":"Надёжный пароль длинный и его трудно угадать. Никому его не говори."},"en":{"title":"Review: passwords","prompt":"Which password is right for a Google account?","options":["Long and hard to guess: letters, digits, symbols","Your own name","12345","Your birthday"],"explanation":"A strong password is long and hard to guess. Tell it to nobody."},"stage":"warmup"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Кесте деген не?","bullets":["Кесте — жолдар мен бағандардан тұратын жиынтық. Ақпаратты кестемен көрсету мәтіннен гөрі оқуға оңай.","Google Docs-тағы кесте ұяшықтарына мәтін, сурет, тіпті басқа кесте салуға болады.","Ұяшық — жол мен бағанның қиылысы."],"art":"anatomy","ru":{"title":"Что такое таблица?","bullets":["Таблица — набор строк и столбцов. Информацию в таблице читать проще, чем в сплошном тексте.","В ячейки таблицы Google Docs можно вставлять текст, рисунки и даже другую таблицу.","Ячейка — пересечение строки и столбца."]},"en":{"title":"What is a table?","bullets":["A table is a set of rows and columns. Information is easier to read in a table than in a paragraph.","Cells of a Google Docs table can hold text, pictures or another table.","A cell is where a row and a column meet."]},"stage":"together","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Google аккаунт және Google Docs","bullets":["gmail.com сайтына кір, «Create an account» бас, форманы толтыр. Аккаунт атына тегің мен атыңды қолдан: omarov.almas.","drive.google.com-да «NEW» → Google Docs таңда. «Untitled document» атын «Менің сабақ кестем» деп ауыстыр.","Аккаунт ашу мектеп ережесіне сай болуы керек. Аккаунт жоқ оқушы ClassFlow кестесінде жұмыс істейді."],"ru":{"title":"Аккаунт Google и Google Docs","bullets":["Зайди на gmail.com, нажми «Create an account», заполни форму. В имени аккаунта используй фамилию и имя: omarov.almas.","На drive.google.com выбери «NEW» → Google Docs. Переименуй «Untitled document» в «Моё расписание».","Аккаунт создаётся по правилам школы. Ученик без аккаунта работает в таблице ClassFlow."],"notes":"Создание аккаунта — дома, с разрешения родителей. На уроке работают те, у кого аккаунт уже есть, остальные — в паре."},"en":{"title":"Google account and Google Docs","bullets":["Go to gmail.com, click “Create an account” and fill in the form. Build the account name from your surname and name: omarov.almas.","On drive.google.com choose “NEW” → Google Docs. Rename “Untitled document” to “My lessons schedule”.","An account must follow the school rules. A student without one works in the ClassFlow sheet."],"notes":"Creating an account is for home, with a parent’s permission. In class those who have one open Docs, the others work in pairs."},"stage":"together","notes":"Аккаунт ашу — үйде, ата-ананың рұқсатымен. Сабақта дайын аккаунты барлар Docs ашады, қалғандары көршісімен жұптасады.","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Сабақ кестесін жасаймыз","bullets":["File → Page setup → Landscape: бетті көлденең етіп аламыз.","Insert → Table → 7 × 9 таңда: 6 күн, күніне 8 сабақ, және тақырып жолы мен бағаны.","Table → Table properties: «Minimum row height» = 1.5, ал бағандар енін 4 қыл. Бірінші баған шекарасын сүйреп те өзгертуге болады."],"ru":{"title":"Делаем расписание уроков","bullets":["File → Page setup → Landscape: делаем страницу альбомной.","Insert → Table → выбери 7 × 9: 6 дней, 8 уроков в день, плюс строка и столбец заголовков.","Table → Table properties: «Minimum row height» = 1.5, ширину столбцов поставь 4. Первый столбец можно тянуть за границу."],"notes":"10 минут. Показывайте шаги на экране, ученики повторяют. 7 × 9 = 63 ячейки: это подготовка к следующей задаче."},"en":{"title":"Making a lesson schedule","bullets":["File → Page setup → Landscape: turn the page sideways.","Insert → Table → choose 7 × 9: 6 days, 8 lessons a day, plus a header row and column.","Table → Table properties: “Minimum row height” = 1.5 and column width 4. You can also drag the border of the first column."],"notes":"10 minutes. Show the steps on the screen while students repeat. 7 × 9 = 63 cells: it prepares the next problem."},"stage":"example","notes":"10 минут. Экраннан қадамдарды көрсетіп, оқушылар қатар қайталайды. 7 × 9 = 63 ұяшық: келесі есептің дайындығы.","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Пішімдеу құралдары","bullets":["Қаріп өлшемі; қалың (Ctrl+B), көлбеу (Ctrl+I), асты сызылған (Ctrl+U) және мәтін түсі.","Туралау: сол жаққа, ортаға, оң жаққа, ені бойынша.","Ұяшықтың фон түсі мен шекара түсі."],"ru":{"title":"Инструменты форматирования","bullets":["Размер шрифта; полужирный (Ctrl+B), курсив (Ctrl+I), подчёркнутый (Ctrl+U) и цвет текста.","Выравнивание: по левому краю, по центру, по правому краю, по ширине.","Цвет заливки ячейки и цвет границ."]},"en":{"title":"Formatting tools","bullets":["Font size; bold (Ctrl+B), italic (Ctrl+I), underline (Ctrl+U) and text colour.","Alignment: left, centre, right, justify.","Cell background colour and border colour."]},"stage":"example","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Практика: менің сабақ кестем","bullets":["Google Docs-та 7 × 9 кесте жасап, апталық сабақ кестеңді толтыр.","Тақырып жолы мен бағанын қалың қаріппен, түспен ерекшеле; мәтінді ұяшық ортасына туралау.","Қосымша: «Сыныптастар туралы» және «Менің бағаларым» кестелерін жаса. Дайын құжатты мұғалімге көрсет."],"ru":{"title":"Практика: моё расписание","bullets":["В Google Docs сделай таблицу 7 × 9 и заполни своё недельное расписание.","Выдели строку и столбец заголовков жирным шрифтом и цветом; выровняй текст по центру ячеек.","Дополнительно: сделай таблицы «Об одноклассниках» и «Мои оценки». Покажи готовый документ учителю."],"notes":"15 минут. Учитель проверяет документ на экране: альбомная страница, 7 × 9, цветной заголовок, выравнивание. Две задачи ниже проверяются автоматически."},"en":{"title":"Practice: my lesson schedule","bullets":["In Google Docs make a 7 × 9 table and fill in your weekly timetable.","Make the header row and column bold and coloured; centre the text in the cells.","Extra: make the tables “About classmates” and “My gradebook”. Show the finished document to the teacher."],"notes":"15 minutes. The teacher checks the document on screen: landscape, 7 × 9, coloured header, alignment. The two problems below are marked automatically."},"stage":"practice","notes":"15 минут. Құжатты мұғалім экраннан тексереді: көлденең бет, 7 × 9, түсті тақырып, туралау. Төмендегі екі есеп — автоматты тексеріледі.","design":"lab"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Есеп: ұяшықтар саны","prompt":"Insert → Table арқылы 7 × 9 кесте қойдық. Ол неше ұяшықтан тұрады?","accept":["63"],"points":2,"ru":{"title":"Задача: число ячеек","prompt":"Мы вставили таблицу 7 × 9 через Insert → Table. Из скольких ячеек она состоит?"},"en":{"title":"Problem: number of cells","prompt":"We inserted a 7 × 9 table with Insert → Table. How many cells does it have?"},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Есеп: жолдар саны","prompt":"Кестеде 6 күн, күніне 8 сабақ. Тақырып бағанын қоссақ, баған саны 7 болады. Тақырып жолын қоссақ, жол саны қанша болады?","accept":["9"],"points":2,"ru":{"title":"Задача: число строк","prompt":"В таблице 6 дней и по 8 уроков в день. С заголовочным столбцом столбцов 7. Сколько будет строк с заголовочной строкой?"},"en":{"title":"Problem: number of rows","prompt":"The table has 6 days and 8 lessons a day. With the header column there are 7 columns. How many rows are there with the header row?"},"stage":"practice"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Ұяшық фоны","prompt":"Ұяшықтың фон түсін өзгерту үшін не істейміз?","options":["Ұяшықты белгілеп, құралдар панелінен фон түсін таңдаймыз","File → Print","Insert → Image","Tools → Spelling"],"answer":0,"explanation":"Фон түсі мен шекара түсі құралдар панелінде ұяшықты белгілегенде өзгереді.","points":1,"ru":{"title":"Фон ячейки","prompt":"Что нужно сделать, чтобы изменить цвет фона ячейки?","options":["Выделить ячейку и выбрать цвет заливки на панели инструментов","File → Print","Insert → Image","Tools → Spelling"],"explanation":"Цвет заливки и границ меняется на панели инструментов после выделения ячейки."},"en":{"title":"Cell background","prompt":"What do we do to change the background colour of a cell?","options":["Select the cell and pick the fill colour on the toolbar","File → Print","Insert → Image","Tools → Spelling"],"explanation":"The fill and border colours change on the toolbar once the cell is selected."},"stage":"check"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Беттің бағыты","prompt":"Бетті көлденең ету қай командамен жасалады?","options":["File → Page setup → Landscape","Insert → Table","Table → Table properties","View → Full screen"],"answer":0,"explanation":"Бет бағыты «Page setup» терезесінде өзгереді: Landscape — көлденең.","points":1,"ru":{"title":"Ориентация страницы","prompt":"Какой командой страница становится альбомной?","options":["File → Page setup → Landscape","Insert → Table","Table → Table properties","View → Full screen"],"explanation":"Ориентация меняется в окне «Page setup»: Landscape — альбомная."},"en":{"title":"Page orientation","prompt":"Which command makes the page landscape?","options":["File → Page setup → Landscape","Insert → Table","Table → Table properties","View → Full screen"],"explanation":"The orientation changes in “Page setup”: Landscape means sideways."},"stage":"check"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"check","title":"Қорытынды: бүгін не үйрендім?","bullets":["Бүгін мен … үйрендім (өз сөзіңмен жалғастыр).","Ең қызықты бөлігі: …","Маған әлі түсініксіз: …"],"ru":{"title":"Итог: что я узнал сегодня?","bullets":["Сегодня я научился … (продолжи своими словами).","Самое интересное: …","Мне пока непонятно: …"],"notes":"Ученики дописывают три предложения в тетрадь, 2–3 ученика читают вслух. Ответы «непонятно» разберите в начале следующего урока."},"en":{"title":"Wrap-up: what did I learn today?","bullets":["Today I learned … (finish in your own words).","The most interesting part: …","I still do not understand: …"],"notes":"Students finish three sentences in a notebook; 2–3 read aloud. Revisit the “do not understand” answers at the start of the next lesson."},"stage":"check","notes":"Оқушылар үш сөйлемді дәптерге жазады, 2–3 оқушы дауыстап оқиды. «Түсініксіз» жауаптарын келесі сабақтың басында қайталаңыз.","design":"lab"}]$s7$::jsonb),
    ($s7$3.2 Электрондық кесте элементтерін пішімдеу$s7$, $s7$Информатика$s7$, 1, $s7${"summary":"Электрондық кесте — жолдар мен бағандардан тұратын электрондық кесте. Ұяшық, жол, баған, парақ ұғымдары; Google Sheets мүмкіндіктері.","objectives":["Электрондық кесте бағдарламасының не екенін түсіндіру","Ұяшық, жол, баған, кесте, парақ ұғымдарын ажырату","Google Sheets-те кесте жасап, ұяшықтарды біріктіру, өлшемін өзгерту, қатыру"],"grade":7,"duration":"45 минут","prior":"Кестенің жолдары мен бағандарын біледі (3.1 сабақ).","env":"Кесте: ClassFlow кестесі немесе Google Sheets. Google Docs/Sheets үшін оқушыда Google аккаунты және интернет болуы керек (аккаунт мектеп ережесіне сай ашылады). Әр оқушыға бір құрылғы.","source":"A. Zhunussov, Ye. Shaniyev, I. Gesen. Informatics, Grade 7, 1st ed., Almaty, 2021, 28–29 беттер. Сабақтағы формулалар мен жауаптар кестеде орындалып тексерілген, деректер ойдан шығарылған.","stages":[{"k":"warmup","min":5,"do":"Кесте және «шығындарды қалай есептейсің?» деген сұраққа жауап береді"},{"k":"together","min":8,"do":"Электрондық кесте не екенін және оның бөліктерін үйренеді"},{"k":"example","min":10,"do":"Мұғаліммен бірге «Істер тізімін» жасап, ұяшықтарды біріктіреді"},{"k":"practice","min":15,"do":"Өз істер тізімін жасап, екі есеп шығарады"},{"k":"check","min":7,"do":"Қысқа тест тапсырады"}],"ru":{"summary":"Электронная таблица состоит из строк и столбцов. Понятия ячейка, строка, столбец, лист; возможности Google Sheets.","objectives":["Объяснять, что такое программа электронных таблиц","Различать понятия ячейка, строка, столбец, таблица, лист","Создавать таблицу в Google Sheets, объединять ячейки, менять размер, закреплять"],"prior":"Знают строки и столбцы таблицы (урок 3.1).","env":"Таблица: ClassFlow или Google Sheets. Для Google Docs/Sheets нужны аккаунт Google и интернет (аккаунт — по правилам школы). Каждому ученику по устройству.","source":"A. Zhunussov, Ye. Shaniyev, I. Gesen. Informatics, Grade 7, 1st ed., Almaty, 2021, с. 28–29. Формулы и ответы урока проверены выполнением в таблице, данные вымышленные.","stages":["Отвечает на вопросы о таблицах и учёте расходов","Узнаёт, что такое электронная таблица и её части","Вместе с учителем делает «Список дел» и объединяет ячейки","Делает свой список дел и решает две задачи","Проходит короткий тест"]},"en":{"summary":"A spreadsheet is an electronic table of rows and columns. Cell, row, column and sheet; what Google Sheets can do.","objectives":["Explain what a spreadsheet program is","Tell cell, row, column, table and sheet apart","Make a table in Google Sheets, merge cells, resize and freeze them"],"prior":"Know the rows and columns of a table (lesson 3.1).","env":"Spreadsheet: the ClassFlow sheet or Google Sheets. Google Docs/Sheets need a Google account and the internet (the account follows the school rules). One device per student.","source":"A. Zhunussov, Ye. Shaniyev, I. Gesen. Informatics, Grade 7, 1st ed., Almaty, 2021, pp. 28–29. The formulas and answers of the lesson were run in a sheet; the data are made up.","stages":["Answers questions about tables and tracking expenses","Learns what a spreadsheet is and its parts","Makes the to-do list with the teacher and merges cells","Builds an own to-do list and solves two problems","Takes a short test"]}}$s7$::jsonb, $s7$[{"term":"spreadsheet","definition":"Электрондық кесте — жолдар мен бағандардан тұратын электрондық кесте · Электронная таблица — таблица из строк и столбцов в электронном виде · Spreadsheet — an electronic table of rows and columns"},{"term":"worksheet","definition":"Парақ — бір толық кесте · Лист — одна таблица целиком · Worksheet — one whole table"},{"term":"merge cells","definition":"Ұяшықтарды біріктіру — бірнеше ұяшықты біреуге қосу · Объединение ячеек — несколько ячеек становятся одной · Merge cells — several cells become one"},{"term":"freeze","definition":"Қатыру — жолды немесе бағанды жылжытқанда орнында қалдыру · Закрепить — строка или столбец остаётся на месте при прокрутке · Freeze — a row or column stays in view when scrolling"}]$s7$::jsonb, $s7$[{"type":"title","pageType":"slide","templateId":"title","title":"3.2 Электрондық кесте элементтерін пішімдеу","subtitle":"Информатика 7-сынып · 3-тарау · оқулық 28–29-б.","ru":{"title":"3.2 Форматирование элементов электронной таблицы","subtitle":"Информатика 7 класс · глава 3 · учебник, с. 28–29"},"en":{"title":"3.2 Formatting spreadsheet elements","subtitle":"Informatics Grade 7 · Chapter 3 · textbook pp. 28–29"},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: бағдарлама","prompt":"Қай бағдарлама электрондық кестемен жұмыс істеуге арналған?","options":["Google Sheets","Paint","Google Chrome","Windows Media Player"],"answer":0,"explanation":"Google Sheets, Excel, Calc — электрондық кесте бағдарламалары.","points":1,"ru":{"title":"Повторение: программа","prompt":"Какая программа предназначена для работы с электронными таблицами?","options":["Google Sheets","Paint","Google Chrome","Windows Media Player"],"explanation":"Google Sheets, Excel, Calc — программы электронных таблиц.","notes":"5 минут. Вопрос: «Как ты считаешь расходы?» — бумага, телефон, таблица. Ответы используем по ходу урока."},"en":{"title":"Review: programs","prompt":"Which program is made for working with spreadsheets?","options":["Google Sheets","Paint","Google Chrome","Windows Media Player"],"explanation":"Google Sheets, Excel and Calc are spreadsheet programs.","notes":"5 minutes. Ask: “How do you track your expenses?” — paper, phone, a table. We use the answers during the lesson."},"stage":"warmup","notes":"5 минут. Сұрақ: «Шығындарыңды қалай есептейсің?» — қағаз, телефон, кесте. Жауапты сабақ ішінде пайдаланамыз."},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: жол және баған","prompt":"Баған дегеніміз не?","options":["Ұяшықтардың тік тізбегі","Ұяшықтардың көлденең тізбегі","Бір ғана ұяшық","Бүкіл құжат"],"answer":0,"explanation":"Баған — тік, жол — көлденең. Баған әріппен (A, B, C), жол санмен (1, 2, 3) белгіленеді.","points":1,"ru":{"title":"Повторение: строка и столбец","prompt":"Что такое столбец?","options":["Вертикальный ряд ячеек","Горизонтальный ряд ячеек","Одна ячейка","Весь документ"],"explanation":"Столбец — вертикальный, строка — горизонтальная. Столбцы обозначают буквами (A, B, C), строки — числами (1, 2, 3)."},"en":{"title":"Review: row and column","prompt":"What is a column?","options":["A vertical set of cells","A horizontal set of cells","A single cell","The whole document"],"explanation":"A column is vertical, a row horizontal. Columns are letters (A, B, C), rows are numbers (1, 2, 3)."},"stage":"warmup"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Электрондық кесте деген не?","bullets":["Электрондық кесте — жолдар мен бағандардан тұратын электронды кесте. Көп мөлшерлі деректерді жеңіл басқаруға көмектеседі.","Ұяшық (cell) — жалғыз деректер элементі; жол (row) — көлденең, баған (column) — тік ұяшықтар тізбегі.","Парақ (sheet) — бір толық кесте; электрондық кесте (spreadsheet) — барлық парақтары бар құжат. Бір құжатта бірнеше парақ болады."],"art":"anatomy","ru":{"title":"Что такое электронная таблица?","bullets":["Электронная таблица состоит из строк и столбцов и помогает легко управлять большими объёмами данных.","Ячейка (cell) — один элемент данных; строка (row) — горизонтальный, столбец (column) — вертикальный ряд.","Лист (sheet) — одна таблица целиком; электронная таблица (spreadsheet) — документ со всеми листами. В документе может быть несколько листов."]},"en":{"title":"What is a spreadsheet?","bullets":["A spreadsheet is an electronic table of columns and rows that makes it easy to manage a lot of data.","A cell is a single data element; a row is a horizontal and a column a vertical set of cells.","A worksheet is one whole table; the spreadsheet is the document with all its sheets. One document can hold several sheets."]},"stage":"together","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Google Sheets мүмкіндіктері","bullets":["Google Sheets браузерде жұмыс істейді, кез келген жүйеде және тегін: орнату керек емес.","Бір кестемен бірнеше адам бір уақытта жұмыс істей алады.","Басқа бағдарламалар да бар: Microsoft Excel, OpenOffice Calc, Numbers (macOS, iOS). Бұл тарауда Google Sheets немесе ClassFlow кестесін қолданамыз."],"ru":{"title":"Возможности Google Sheets","bullets":["Google Sheets работает в браузере, в любой системе и бесплатно: ничего устанавливать не нужно.","С одной таблицей могут работать несколько человек одновременно.","Есть и другие программы: Microsoft Excel, OpenOffice Calc, Numbers (macOS, iOS). В этой главе работаем в Google Sheets или в таблице ClassFlow."]},"en":{"title":"What Google Sheets can do","bullets":["Google Sheets runs in a browser, on any system, for free: nothing to install.","Several people can work in the same sheet at the same time.","There are other programs: Microsoft Excel, OpenOffice Calc, Numbers (macOS, iOS). In this chapter we use Google Sheets or the ClassFlow sheet."]},"stage":"together","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Істер тізімі","bullets":["Жаңа кесте ашып, атын «Менің істер тізімім» деп өзгерт.","A1:D1 ұяшықтарын белгілеп, «Merge cells» бас — тақырып бір ұяшық болады.","Мәтін ұяшыққа сыймаса, жол өлшемін өзгерт немесе «Text wrapping» қос. Бағанның шетін екі рет шертсең, ені өздігінен сәйкестенеді."],"demoSheet":{"rows":8,"cols":4,"cells":{"A1":"Менің істер тізімім","A2":"№","B2":"Іс","C2":"Мерзімі","D2":"Орындалды","A3":"1","B3":"Информатикадан үй тапсырмасы","C3":"Дүйсенбі","D3":"Иә","A4":"2","B4":"Кітап оқу","C4":"Сәрсенбі","D4":"Жоқ","A5":"3","B5":"Спорт секциясы","C5":"Жұма","D5":"Жоқ"},"fmt":{"A1":{"b":1,"bg":"#dbeafe"},"A2":{"b":1,"bg":"#dbeafe"},"B2":{"b":1,"bg":"#dbeafe"},"C2":{"b":1,"bg":"#dbeafe"},"D2":{"b":1,"bg":"#dbeafe"}}},"notes":"8 минут. Біріктіру (Merge), өлшемді өзгерту және «View → Freeze» (жолды бекіту) командаларын көрсетіңіз: бекітілген жол төмен жылжытқанда да көрініп тұрады.","ru":{"title":"Список дел","bullets":["Открой новую таблицу и назови её «Мой список дел».","Выдели A1:D1 и нажми «Merge cells» — заголовок станет одной ячейкой.","Если текст не помещается, измени размер строки или включи «Text wrapping». Двойной щелчок по краю столбца подгоняет ширину."],"demoSheet":{"rows":8,"cols":4,"cells":{"A1":"Мой список дел","A2":"№","B2":"Дело","C2":"Срок","D2":"Выполнено","A3":"1","B3":"Домашнее задание по информатике","C3":"Понедельник","D3":"Да","A4":"2","B4":"Чтение книги","C4":"Среда","D4":"Нет","A5":"3","B5":"Спортивная секция","C5":"Пятница","D5":"Нет"},"fmt":{"A1":{"b":1,"bg":"#dbeafe"},"A2":{"b":1,"bg":"#dbeafe"},"B2":{"b":1,"bg":"#dbeafe"},"C2":{"b":1,"bg":"#dbeafe"},"D2":{"b":1,"bg":"#dbeafe"}}},"notes":"8 минут. Покажите Merge, изменение размера и «View → Freeze»: закреплённая строка остаётся на месте при прокрутке."},"en":{"title":"To-do list","bullets":["Open a new sheet and name it “My to-do list”.","Select A1:D1 and click “Merge cells” — the title becomes one cell.","If the text does not fit, resize the row or turn on “Text wrapping”. Double-click a column edge to fit it."],"demoSheet":{"rows":8,"cols":4,"cells":{"A1":"My to-do list","A2":"#","B2":"Task","C2":"Due","D2":"Done","A3":"1","B3":"Informatics homework","C3":"Monday","D3":"Yes","A4":"2","B4":"Read a book","C4":"Wednesday","D4":"No","A5":"3","B5":"Sports club","C5":"Friday","D5":"No"},"fmt":{"A1":{"b":1,"bg":"#dbeafe"},"A2":{"b":1,"bg":"#dbeafe"},"B2":{"b":1,"bg":"#dbeafe"},"C2":{"b":1,"bg":"#dbeafe"},"D2":{"b":1,"bg":"#dbeafe"}}},"notes":"8 minutes. Show Merge, resizing and “View → Freeze”: a frozen row stays in view when scrolling."},"stage":"together"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Қосымша командалар","bullets":["Merge cells — бірнеше ұяшықты біреуге біріктіру.","Өлшемді өзгерту: баған немесе жол шетін сүйре; автоматты өлшем үшін шетін екі рет шерт.","View → Freeze: таңдалған жолды немесе бағанды қатырып, жылжытқанда жоғалмайтындай етеді."],"ru":{"title":"Дополнительные команды","bullets":["Merge cells — объединить несколько ячеек в одну.","Изменение размера: тяни за край столбца или строки; двойной щелчок по краю подгоняет размер сам.","View → Freeze: закрепляет строку или столбец, чтобы они не пропадали при прокрутке."]},"en":{"title":"More commands","bullets":["Merge cells joins several cells into one.","To resize, drag a column or row edge; a double click on the edge fits it automatically.","View → Freeze pins a row or column so it stays in view while scrolling."]},"stage":"example","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Практика: менің істер тізімім","bullets":["Кесте жаса: № | Іс | Мерзімі | Орындалды бағандары, кемінде бес жол.","Тақырыпты біріктір, тақырып жолын қалың қыл, ұзын мәтінге Text wrapping қос.","Тақырып жолын қатыр. Дайын кестені мұғалімге көрсет."],"ru":{"title":"Практика: мой список дел","bullets":["Сделай таблицу со столбцами № | Дело | Срок | Выполнено, не меньше пяти строк.","Объедини ячейки заголовка, сделай строку заголовков жирной, для длинного текста включи Text wrapping.","Закрепи строку заголовков. Покажи готовую таблицу учителю."],"notes":"15 минут. Форматирование учитель смотрит на экране. Две задачи ниже проверяются автоматически."},"en":{"title":"Practice: my to-do list","bullets":["Make a table with the columns # | Task | Due | Done and at least five rows.","Merge the title cells, make the header row bold and turn on Text wrapping for long text.","Freeze the header row. Show the finished table to the teacher."],"notes":"15 minutes. The teacher checks the formatting on screen. The two problems below are marked automatically."},"stage":"practice","notes":"15 минут. Пішімдеуді мұғалім экраннан қарайды. Төмендегі екі есеп автоматты тексеріледі.","design":"lab"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Есеп: ұяшықтар","prompt":"Кесте A1:D6 ұяшықтарында орналасқан. Онда неше ұяшық бар?","accept":["24"],"points":2,"notes":"4 баған × 6 жол = 24.","ru":{"title":"Задача: ячейки","prompt":"Таблица занимает ячейки A1:D6. Сколько в ней ячеек?","notes":"4 столбца × 6 строк = 24."},"en":{"title":"Problem: cells","prompt":"A table occupies cells A1:D6. How many cells does it have?","notes":"4 columns × 6 rows = 24."},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Есеп: жолдар саны","prompt":"Кесте B3:E10 диапазонында. Онда неше жол бар?","accept":["8"],"points":2,"notes":"3-жолдан 10-жолға дейін: 10 − 3 + 1 = 8.","ru":{"title":"Задача: число строк","prompt":"Таблица находится в диапазоне B3:E10. Сколько в ней строк?","notes":"С 3-й по 10-ю строку: 10 − 3 + 1 = 8."},"en":{"title":"Problem: number of rows","prompt":"A table sits in the range B3:E10. How many rows does it have?","notes":"From row 3 to row 10: 10 − 3 + 1 = 8."},"stage":"practice"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Ұяшықтарды біріктіру","prompt":"Бірнеше ұяшықты біреуге қосатын команда қайсы?","options":["Merge cells","Freeze","Text wrapping","Borders"],"answer":0,"explanation":"Merge cells ұяшықтарды біріктіреді; Freeze қатырады; Text wrapping мәтінді жолдарға бөледі.","points":1,"ru":{"title":"Объединение ячеек","prompt":"Какая команда соединяет несколько ячеек в одну?","options":["Merge cells","Freeze","Text wrapping","Borders"],"explanation":"Merge cells объединяет; Freeze закрепляет; Text wrapping переносит текст на несколько строк."},"en":{"title":"Merging cells","prompt":"Which command joins several cells into one?","options":["Merge cells","Freeze","Text wrapping","Borders"],"explanation":"Merge cells joins; Freeze pins; Text wrapping breaks the text into lines."},"stage":"check"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Google Sheets артықшылығы","prompt":"Google Sheets-тің басқа бағдарламалардан басты артықшылығы қандай?","options":["Браузерде тегін жұмыс істейді, бірнеше адам бірге өңдей алады","Тек бір компьютерде жұмыс істейді","Интернетсіз ғана жұмыс істейді","Кесте жасай алмайды"],"answer":0,"explanation":"Google Sheets онлайн, тегін және бірлесіп өңдеуге болады.","points":1,"ru":{"title":"Плюс Google Sheets","prompt":"Какое главное преимущество Google Sheets?","options":["Работает в браузере бесплатно, несколько человек редактируют вместе","Работает только на одном компьютере","Работает только без интернета","Не умеет делать таблицы"],"explanation":"Google Sheets онлайн, бесплатный и допускает совместную работу."},"en":{"title":"Google Sheets advantage","prompt":"What is the main advantage of Google Sheets?","options":["Free in a browser, and several people can edit together","Works on one computer only","Works only offline","Cannot make tables"],"explanation":"Google Sheets is online, free and allows shared editing."},"stage":"check"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"check","title":"Қорытынды: бүгін не үйрендім?","bullets":["Бүгін мен … үйрендім (өз сөзіңмен жалғастыр).","Ең қызықты бөлігі: …","Маған әлі түсініксіз: …"],"ru":{"title":"Итог: что я узнал сегодня?","bullets":["Сегодня я научился … (продолжи своими словами).","Самое интересное: …","Мне пока непонятно: …"],"notes":"Ученики дописывают три предложения в тетрадь, 2–3 ученика читают вслух. Ответы «непонятно» разберите в начале следующего урока."},"en":{"title":"Wrap-up: what did I learn today?","bullets":["Today I learned … (finish in your own words).","The most interesting part: …","I still do not understand: …"],"notes":"Students finish three sentences in a notebook; 2–3 read aloud. Revisit the “do not understand” answers at the start of the next lesson."},"stage":"check","notes":"Оқушылар үш сөйлемді дәптерге жазады, 2–3 оқушы дауыстап оқиды. «Түсініксіз» жауаптарын келесі сабақтың басында қайталаңыз.","design":"lab"}]$s7$::jsonb),
    ($s7$3.3 Кесте элементтерін пішімдеу. Деректер түрлері$s7$, $s7$Информатика$s7$, 2, $s7${"summary":"Туралау, қаріп, түс, шекара. Деректер түрлері: сан, пайыз, валюта, күн, уақыт, мәтін; ұяшыққа дұрыс түр беру.","objectives":["Ұяшықты пішімдеу құралдарын атау және қолдану","Деректер түрлерін ажырату: сан, пайыз, валюта, күн, уақыт, мәтін","Әр ақпаратқа сәйкес деректер түрін таңдау"],"grade":7,"duration":"45 минут","prior":"Кестенің жолдары мен бағандарын, ұяшықты біледі; Google Sheets-те кесте жасай алады (3.2 сабақ).","env":"Кесте: ClassFlow кестесі немесе Google Sheets. Google Docs/Sheets үшін оқушыда Google аккаунты және интернет болуы керек (аккаунт мектеп ережесіне сай ашылады). Әр оқушыға бір құрылғы.","source":"A. Zhunussov, Ye. Shaniyev, I. Gesen. Informatics, Grade 7, 1st ed., Almaty, 2021, 30–31 беттер. Сабақтағы формулалар мен жауаптар кестеде орындалып тексерілген, деректер ойдан шығарылған.","stages":[{"k":"warmup","min":5,"do":"Туралау және сан түрі туралы екі сұраққа жауап береді"},{"k":"together","min":8,"do":"Пішімдеу құралдарын және деректер түрлерінің кестесін үйренеді"},{"k":"example","min":10,"do":"Мұғаліммен бірге «Емтихан нәтижелері» кестесінің пішімін таңдайды"},{"k":"practice","min":15,"do":"Валюта калькуляторын жасайды, емтихан кестесін пішімдейді"},{"k":"check","min":7,"do":"Қысқа тест тапсырып, не үйренгенін айтады"}],"ru":{"summary":"Выравнивание, шрифт, цвет, границы. Типы данных: число, процент, валюта, дата, время, текст; выбор правильного типа ячейки.","objectives":["Называть и применять инструменты форматирования ячеек","Различать типы данных: число, процент, валюта, дата, время, текст","Выбирать подходящий тип данных для каждой информации"],"prior":"Знают строки, столбцы и ячейку; умеют создать таблицу в Google Sheets (урок 3.2).","env":"Таблица: ClassFlow или Google Sheets. Для Google Docs/Sheets нужны аккаунт Google и интернет (аккаунт — по правилам школы). Каждому ученику по устройству.","source":"A. Zhunussov, Ye. Shaniyev, I. Gesen. Informatics, Grade 7, 1st ed., Almaty, 2021, с. 30–31. Формулы и ответы урока проверены выполнением в таблице, данные вымышленные.","stages":["Отвечает на два вопроса о выравнивании и типе числа","Изучает инструменты форматирования и таблицу типов данных","Вместе с учителем подбирает формат таблицы «Результаты экзаменов»","Делает калькулятор валют и форматирует таблицу экзаменов","Проходит короткий тест и говорит, что узнал"]},"en":{"summary":"Alignment, font, colour, borders. Data types: number, percent, currency, date, time, text, and picking the right one for a cell.","objectives":["Name and use the cell formatting tools","Tell data types apart: number, percent, currency, date, time, text","Choose the right data type for each piece of information"],"prior":"Know rows, columns and cells; can make a table in Google Sheets (lesson 3.2).","env":"Spreadsheet: the ClassFlow sheet or Google Sheets. Google Docs/Sheets need a Google account and the internet (the account follows the school rules). One device per student.","source":"A. Zhunussov, Ye. Shaniyev, I. Gesen. Informatics, Grade 7, 1st ed., Almaty, 2021, pp. 30–31. The formulas and answers of the lesson were run in a sheet; the data are made up.","stages":["Answers two questions about alignment and number type","Learns the formatting tools and the table of data types","Picks the formats of the “Exam results” table with the teacher","Builds a currency calculator and formats the exam table","Takes a short test and says what was learned"]}}$s7$::jsonb, $s7$[{"term":"alignment","definition":"Туралау — деректің ұяшықтағы орны · Выравнивание — положение данных в ячейке · Alignment — the position of data in a cell"},{"term":"data type","definition":"Деректер түрі — ұяшықта қандай мән сақталатынын көрсетеді: сан, пайыз, валюта, күн… · Тип данных — показывает, какое значение хранится в ячейке: число, процент, валюта, дата… · Data type — tells what kind of value a cell stores: number, percent, currency, date…"},{"term":"number format","definition":"Сан пішімі — санның көрінісі: 5, 50%, $2,999 · Числовой формат — вид числа: 5, 50%, $2,999 · Number format — how a number looks: 5, 50%, $2,999"}]$s7$::jsonb, $s7$[{"type":"title","pageType":"slide","templateId":"title","title":"3.3 Кесте элементтерін пішімдеу. Деректер түрлері","subtitle":"Информатика 7-сынып · 3-тарау · оқулық 30–31-б.","ru":{"title":"3.3 Форматирование таблицы. Типы данных","subtitle":"Информатика 7 класс · глава 3 · учебник, с. 30–31"},"en":{"title":"3.3 Formatting a table. Data types","subtitle":"Informatics Grade 7 · Chapter 3 · textbook pp. 30–31"},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: туралау","prompt":"Туралау (alignment) нені көрсетеді?","options":["Деректің ұяшықтағы орнын: сол, орта, оң","Қаріп түрін","Ұяшық фонын","Беттің бағытын"],"answer":0,"explanation":"Alignment — деректің ұяшықтағы орны: көлденеңінен (сол, орта, оң) және тігінен (жоғары, орта, төмен).","points":1,"ru":{"title":"Повторение: выравнивание","prompt":"Что определяет выравнивание (alignment)?","options":["Положение данных в ячейке: слева, по центру, справа","Тип шрифта","Фон ячейки","Ориентацию страницы"],"explanation":"Alignment — положение данных в ячейке: по горизонтали (слева, по центру, справа) и по вертикали (сверху, по центру, снизу).","notes":"5 минут. Спросите: «Как ты учитываешь расходы?» — это вводит в тему."},"en":{"title":"Review: alignment","prompt":"What does alignment set?","options":["The position of data in a cell: left, centre, right","The font type","The cell background","The page orientation"],"explanation":"Alignment is where data sits in a cell: horizontally (left, centre, right) and vertically (top, middle, bottom).","notes":"5 minutes. Ask: “How do you track your expenses?” — it leads into the topic."},"stage":"warmup","notes":"5 минут. Сұрақ: «Шығындарыңды қалай есептейсің?» — тақырыпқа кіріспе."},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: түс","prompt":"Ұяшық фонының түсін қай құрал өзгертеді?","options":["Fill color","Text color","Borders","Font size"],"answer":0,"explanation":"Fill color — ұяшық фоны, Text color — мәтін түсі, Borders — шекара.","points":1,"ru":{"title":"Повторение: цвет","prompt":"Какой инструмент меняет цвет фона ячейки?","options":["Fill color","Text color","Borders","Font size"],"explanation":"Fill color — фон ячейки, Text color — цвет текста, Borders — границы."},"en":{"title":"Review: colours","prompt":"Which tool changes the background colour of a cell?","options":["Fill color","Text color","Borders","Font size"],"explanation":"Fill color is the cell background, Text color the text, Borders the lines."},"stage":"warmup"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Пішімдеу құралдары","bullets":["Alignment — деректің орны; Font — қаріп түрі; Font size — өлшемі; Font style — қалың және көлбеу.","Text color — мәтін түсі, Fill color — ұяшық фоны, Borders — кесте шекарасы.","Тақырып жолын түспен және қалың қаріппен ерекшелесең, кестені оқу жеңіл болады."],"art":"anatomy","ru":{"title":"Инструменты форматирования","bullets":["Alignment — положение данных; Font — тип шрифта; Font size — размер; Font style — полужирный и курсив.","Text color — цвет текста, Fill color — фон ячейки, Borders — границы таблицы.","Если заголовки выделить цветом и жирным шрифтом, таблицу легче читать."]},"en":{"title":"Formatting tools","bullets":["Alignment sets the position; Font the type; Font size the size; Font style bold and italic.","Text color colours the text, Fill color the cell, Borders draw the lines of the table.","A header row in colour and bold makes the table easier to read."]},"stage":"together","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Деректер түрлері","bullets":["Сан пішімі — ұяшықта қандай мән сақталатынын кестеге айтатын түр: сан, пайыз, валюта, күн, уақыт.","Number — 5; 6.5. Percent — 50.00%. Currency — $2,999.00. Date — 17-09-2016. Time — 13:30. Plain text — әріптер, таңбалар.","Неге керек? Дұрыс түр болса, кесте мәнді дұрыс көрсетеді және есептейді: күнді азайтуға болады, мәтінді болмайды."],"ru":{"title":"Типы данных","bullets":["Числовой формат — тип, по которому таблица понимает, что хранится в ячейке: число, процент, валюта, дата, время.","Number — 5; 6.5. Percent — 50.00%. Currency — $2,999.00. Date — 17-09-2016. Time — 13:30. Plain text — буквы, знаки.","Зачем? С правильным типом таблица верно показывает и считает: даты можно вычитать, а тексты нельзя."],"notes":"8 минут. Покажите таблицу 3.3.4 из учебника. Вопрос: «Какой тип у номера телефона?» (Plain text — с ним мы не считаем)."},"en":{"title":"Data types","bullets":["A number format tells the sheet what kind of value a cell stores: number, percent, currency, date, time.","Number — 5; 6.5. Percent — 50.00%. Currency — $2,999.00. Date — 17-09-2016. Time — 13:30. Plain text — letters, symbols.","Why? With the right type the sheet shows and calculates correctly: dates can be subtracted, plain text cannot."],"notes":"8 minutes. Show table 3.3.4 of the textbook. Ask: “What type is a phone number?” (Plain text — we do not calculate with it)."},"stage":"together","notes":"8 минут. Оқулықтағы 3.3.4 кестесін экраннан көрсетіңіз. Сұрақ: «Телефон нөмірі қандай түр?» (Plain text — онымен есептемейміз).","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Мысал: емтихан нәтижелері","bullets":["A1:D1 тақырыбын қалың етіп, фонын боя; мәтінді ортаға туралау.","C бағанын Percent түріне ауыстыр: «Format → Number → Percent».","D бағанындағы күнді Date түрімен көрсет. Мәтін ұяшықтарын (A бағаны) Plain text қалдыр."],"demoSheet":{"rows":6,"cols":4,"cells":{"A1":"Пән","B1":"Балл","C1":"Орындалды, %","D1":"Күні","A2":"Математика","B2":"45","C2":"90%","D2":"12.12.2026","A3":"Информатика","B3":"48","C3":"96%","D3":"14.12.2026","A4":"Ағылшын тілі","B4":"40","C4":"80%","D4":"16.12.2026"},"fmt":{"A1":{"b":1,"bg":"#dbeafe","al":"center"},"B1":{"b":1,"bg":"#dbeafe","al":"center"},"C1":{"b":1,"bg":"#dbeafe","al":"center"},"D1":{"b":1,"bg":"#dbeafe","al":"center"}}},"notes":"10 минут. Оқушылар пішімді өз кестесінде қайталайды. Көрсететін жайт: «90%» мәтін емес, сан (0.9) — Percent түрі оны осылай көрсетеді. Мәтін ұяшығын Date түріне ауыстырғанда не болатынын сұраңыз.","ru":{"title":"Пример: результаты экзаменов","bullets":["Сделай заголовки A1:D1 жирными, залей фон; выровняй текст по центру.","Столбец C переведи в Percent: «Format → Number → Percent».","Дату в столбце D покажи в формате Date. Текстовые ячейки (столбец A) оставь Plain text."],"demoSheet":{"rows":6,"cols":4,"cells":{"A1":"Предмет","B1":"Балл","C1":"Выполнено, %","D1":"Дата","A2":"Математика","B2":"45","C2":"90%","D2":"12.12.2026","A3":"Информатика","B3":"48","C3":"96%","D3":"14.12.2026","A4":"Английский язык","B4":"40","C4":"80%","D4":"16.12.2026"},"fmt":{"A1":{"b":1,"bg":"#dbeafe","al":"center"},"B1":{"b":1,"bg":"#dbeafe","al":"center"},"C1":{"b":1,"bg":"#dbeafe","al":"center"},"D1":{"b":1,"bg":"#dbeafe","al":"center"}}},"notes":"10 минут. Ученики повторяют форматирование у себя. Покажите: «90%» — не текст, а число (0.9); так его показывает тип Percent. Спросите, что будет, если текстовую ячейку перевести в Date."},"en":{"title":"Example: exam results","bullets":["Make the headers A1:D1 bold, fill the background and centre the text.","Switch column C to Percent: “Format → Number → Percent”.","Show the dates in column D as Date. Leave the text cells (column A) as Plain text."],"demoSheet":{"rows":6,"cols":4,"cells":{"A1":"Subject","B1":"Score","C1":"Done, %","D1":"Date","A2":"Maths","B2":"45","C2":"90%","D2":"12.12.2026","A3":"Informatics","B3":"48","C3":"96%","D3":"14.12.2026","A4":"English","B4":"40","C4":"80%","D4":"16.12.2026"},"fmt":{"A1":{"b":1,"bg":"#dbeafe","al":"center"},"B1":{"b":1,"bg":"#dbeafe","al":"center"},"C1":{"b":1,"bg":"#dbeafe","al":"center"},"D1":{"b":1,"bg":"#dbeafe","al":"center"}}},"notes":"10 minutes. Students repeat the formatting in their own sheet. Point out that “90%” is not text but the number 0.9, and Percent type just shows it that way. Ask what happens if a text cell is switched to Date."},"stage":"example"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"practice","title":"Практика 1 және 2: пішімдеу","bullets":["Google Sheets-те «Істер тізімі» кестесін оқулықтағы үлгі бойынша түрлендір: туралау, қаріп, түс, шекара.","Өз емтихан нәтижелерің кестесін жаса. Әр ұяшыққа дұрыс деректер түрін таңда да, әдемі пішімде.","Мұғалім кестені экраннан тексереді. Төмендегі валюта есебі автоматты тексеріледі."],"ru":{"title":"Практика 1 и 2: форматирование","bullets":["В Google Sheets измени таблицу «Список дел» по образцу: выравнивание, шрифт, цвет, границы.","Сделай таблицу своих результатов экзаменов. Выбери для каждой ячейки правильный тип данных и оформи.","Учитель проверяет таблицу на экране. Задача про валюту ниже проверяется автоматически."],"notes":"15 минут. Форматирование проверяйте глазами: выделены ли заголовки, числа, проценты и даты в верном типе. Автоматически проверяется калькулятор валют ниже."},"en":{"title":"Practice 1 and 2: formatting","bullets":["In Google Sheets modify your “To-do list” by the sample: alignment, font, colour, borders.","Make a table of your own exam results. Choose the right data type for each cell and format it nicely.","The teacher checks the table on screen. The currency problem below is marked automatically."],"notes":"15 minutes. Check the formatting by eye: are the headers marked, are numbers, percents and dates in the right type. The currency calculator below is the auto-marked part."},"stage":"practice","notes":"15 минут. Пішімдеуді сызбадан тексеру: тақырып ерекшеленген бе, сан, пайыз және күн дұрыс түрде ме. Автоматты тексерілетін бөлік — төмендегі валюта калькуляторы.","design":"lab"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Практика 3: валюта калькуляторы","prompt":"Кестедегі бағаларды теңгеге ауыстыр: баға × бағам. Қосындыны және ең қымбат тауарды тап.","points":10,"picture":"lec/inf8-g7-fx-kk.svg","pictureAlt":"Төрт тауардың шетел валютасындағы бағасы мен бағамы; теңгедегі баға, қосынды және ең үлкен мән бос","sheet":{"rows":14,"cols":8},"criteria":[{"id":"c1","text":"Деректер енгізілген: B2 = 12 және C5 = 520","cell":"C5","points":1,"accept":["520"]},{"id":"c2","text":"D2 — кітаптың теңгедегі бағасы (формула)","cell":"D2","points":2,"formula":true,"accept":["5760"]},{"id":"c3","text":"D3 — сағаттың теңгедегі бағасы","cell":"D3","points":2,"formula":true,"accept":["15600"]},{"id":"c4","text":"D4 және D5 — қалған екі тауар","cell":"D5","points":1,"formula":true,"accept":["1040"]},{"id":"c5","text":"D6 — барлық тауардың қосындысы (SUM)","cell":"D6","points":2,"fn":"SUM","accept":["23840"]},{"id":"c6","text":"★ D7 — ең қымбат тауардың бағасы (MAX)","cell":"D7","points":2,"fn":"MAX","accept":["15600"]}],"steps":["Көмек: D2 ұяшығына =B2*C2 жаз да, D5-ке дейін төмен тарт.","D6-ға =SUM(D2:D5) жаз.","★ Күрделі: D7-ге =MAX(D2:D5) жаз. Бағаны Currency түрімен көрсетіп көр."],"notes":"Күтілетін нәтиже: D2 = 5760, D3 = 15600, D4 = 1440, D5 = 1040; D6 = 23840; D7 = 15600. Бағамдар — оқуға арналған ойдан шығарылған сандар, нақты бағам емес. Жиі қате: бағамды формулаға санмен жазу (=B2*480) — кесте жұмыс істейді, бірақ бағам өзгерсе, формуланы қайта жазу керек болады.","ru":{"title":"Практика 3: калькулятор валют","prompt":"Переведи цены из таблицы в тенге: цена × курс. Найди сумму и самый дорогой товар.","picture":"lec/inf8-g7-fx-ru.svg","pictureAlt":"Цены четырёх товаров в валюте и курс; цена в тенге, сумма и максимум пустые","criteria":[{"id":"c1","text":"Данные введены: B2 = 12 и C5 = 520","cell":"C5","points":1},{"id":"c2","text":"D2 — цена книги в тенге (формула)","cell":"D2","points":2,"formula":true},{"id":"c3","text":"D3 — цена часов в тенге","cell":"D3","points":2,"formula":true},{"id":"c4","text":"D4 и D5 — остальные два товара","cell":"D5","points":1,"formula":true},{"id":"c5","text":"D6 — сумма всех товаров (SUM)","cell":"D6","points":2,"fn":"SUM"},{"id":"c6","text":"★ D7 — цена самого дорогого товара (MAX)","cell":"D7","points":2,"fn":"MAX"}],"steps":["Подсказка: в D2 запиши =B2*C2 и протяни вниз до D5.","В D6 запиши =SUM(D2:D5).","★ Сложнее: в D7 запиши =MAX(D2:D5). Попробуй показать цену в формате Currency."],"notes":"Ожидаемый результат: D2 = 5760, D3 = 15600, D4 = 1440, D5 = 1040; D6 = 23840; D7 = 15600. Курсы — учебные придуманные числа, не реальные. Частая ошибка: вписать курс числом в формулу (=B2*480): работает, но при смене курса формулы придётся переписывать."},"en":{"title":"Practice 3: currency calculator","prompt":"Convert the prices in the table into tenge: price × rate. Find the total and the most expensive item.","picture":"lec/inf8-g7-fx-en.svg","pictureAlt":"Four goods with price in foreign currency and the rate; tenge price, total and maximum left empty","criteria":[{"id":"c1","text":"Data entered: B2 = 12 and C5 = 520","cell":"C5","points":1},{"id":"c2","text":"D2 — the book price in tenge (formula)","cell":"D2","points":2,"formula":true},{"id":"c3","text":"D3 — the watch price in tenge","cell":"D3","points":2,"formula":true},{"id":"c4","text":"D4 and D5 — the other two items","cell":"D5","points":1,"formula":true},{"id":"c5","text":"D6 — total of all items (SUM)","cell":"D6","points":2,"fn":"SUM"},{"id":"c6","text":"★ D7 — the price of the most expensive item (MAX)","cell":"D7","points":2,"fn":"MAX"}],"steps":["Hint: in D2 type =B2*C2 and drag down to D5.","In D6 type =SUM(D2:D5).","★ Challenge: in D7 type =MAX(D2:D5). Try showing the price as Currency."],"notes":"Expected: D2 = 5760, D3 = 15600, D4 = 1440, D5 = 1040; D6 = 23840; D7 = 15600. The rates are made-up classroom numbers, not real ones. Common slip: typing the rate into the formula (=B2*480): it works but must be rewritten when the rate changes."},"stage":"practice"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Деректер түрі: күн","prompt":"«17-09-2016» жазуы қай түрге жатады?","options":["Date","Currency","Percent","Scientific"],"answer":0,"explanation":"Күн жазуы Date түрімен сақталады, оған қосу мен азайту амалдарын қолдануға болады.","points":1,"ru":{"title":"Тип данных: дата","prompt":"К какому типу относится запись «17-09-2016»?","options":["Date","Currency","Percent","Scientific"],"explanation":"Запись даты хранится как Date, с датами можно складывать и вычитать."},"en":{"title":"Data type: date","prompt":"Which type is “17-09-2016”?","options":["Date","Currency","Percent","Scientific"],"explanation":"A date is stored as Date; you can add and subtract dates."},"stage":"check"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Деректер түрі: валюта","prompt":"$2,999.00 жазуы қандай түр?","options":["Currency","Plain text","Time","Duration"],"answer":0,"explanation":"Currency — валюта белгісі бар сан; Currency (rounded) оны бүтінге дейін дөңгелектейді.","points":1,"ru":{"title":"Тип данных: валюта","prompt":"К какому типу относится запись $2,999.00?","options":["Currency","Plain text","Time","Duration"],"explanation":"Currency — число со знаком валюты; Currency (rounded) округляет его до целых."},"en":{"title":"Data type: currency","prompt":"Which type is $2,999.00?","options":["Currency","Plain text","Time","Duration"],"explanation":"Currency is a number with a currency sign; Currency (rounded) rounds it to whole units."},"stage":"check"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Қысқа сұрақ: түр","prompt":"Телефон нөмірімен есептемейміз. Оған қандай деректер түрін қояды? (екі сөз, ағылшынша)","accept":["plain text"],"points":1,"ru":{"title":"Короткий вопрос: тип","prompt":"С номером телефона мы не считаем. Какой тип данных ему ставят? (два слова, по-английски)"},"en":{"title":"Short question: type","prompt":"We do not calculate with a phone number. Which data type fits it? (two words, in English)"},"stage":"check"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"check","title":"Қорытынды: бүгін не үйрендім?","bullets":["Бүгін мен … үйрендім (өз сөзіңмен жалғастыр).","Ең қызықты бөлігі: …","Маған әлі түсініксіз: …"],"ru":{"title":"Итог: что я узнал сегодня?","bullets":["Сегодня я научился … (продолжи своими словами).","Самое интересное: …","Мне пока непонятно: …"],"notes":"Ученики дописывают три предложения в тетрадь, 2–3 ученика читают вслух. Ответы «непонятно» разберите в начале следующего урока."},"en":{"title":"Wrap-up: what did I learn today?","bullets":["Today I learned … (finish in your own words).","The most interesting part: …","I still do not understand: …"],"notes":"Students finish three sentences in a notebook; 2–3 read aloud. Revisit the “do not understand” answers at the start of the next lesson."},"stage":"check","notes":"Оқушылар үш сөйлемді дәптерге жазады, 2–3 оқушы дауыстап оқиды. «Түсініксіз» жауаптарын келесі сабақтың басында қайталаңыз.","design":"lab"}]$s7$::jsonb),
    ($s7$3.4 Деректер түрлері: формулалар мен пайыз$s7$, $s7$Информатика$s7$, 3, $s7${"summary":"Формула «=» таңбасынан басталады; көшіргенде сілтеме өзгереді. Функция және диапазон. Сан, күн және пайыз пішімдері.","objectives":["Ұяшық адресі мен диапазонды дұрыс жазу","Формула жазып, оны басқа ұяшыққа көшіру","Пайызды есептеу: «х-тың у-ке қатынасы» және «санның бөлігі»"],"grade":7,"duration":"45 минут","prior":"Деректер түрлерін біледі (3.3 сабақ), ұяшық адресін оқи алады.","env":"Кесте: ClassFlow кестесі немесе Google Sheets. Google Docs/Sheets үшін оқушыда Google аккаунты және интернет болуы керек (аккаунт мектеп ережесіне сай ашылады). Әр оқушыға бір құрылғы.","source":"A. Zhunussov, Ye. Shaniyev, I. Gesen. Informatics, Grade 7, 1st ed., Almaty, 2021, 32–33 беттер. Сабақтағы формулалар мен жауаптар кестеде орындалып тексерілген, деректер ойдан шығарылған.","stages":[{"k":"warmup","min":5,"do":"Адрес пен диапазон туралы екі сұраққа жауап береді"},{"k":"together","min":8,"do":"Формула, функция, диапазон ұғымдарын үйренеді"},{"k":"example","min":10,"do":"Мұғаліммен бірге формуланы көшіріп, пайызды есептейді"},{"k":"practice","min":15,"do":"Формуланы көшіру, пайыз және күн есептерін шығарады"},{"k":"check","min":7,"do":"Қысқа тест тапсырып, не үйренгенін айтады"}],"ru":{"summary":"Формула начинается с «=»; при копировании ссылки меняются. Функция и диапазон. Форматы числа, даты и процента.","objectives":["Правильно записывать адрес ячейки и диапазон","Записывать формулу и копировать её в другую ячейку","Считать проценты: «какую часть составляет» и «часть от числа»"],"prior":"Знают типы данных (урок 3.3) и умеют читать адрес ячейки.","env":"Таблица: ClassFlow или Google Sheets. Для Google Docs/Sheets нужны аккаунт Google и интернет (аккаунт — по правилам школы). Каждому ученику по устройству.","source":"A. Zhunussov, Ye. Shaniyev, I. Gesen. Informatics, Grade 7, 1st ed., Almaty, 2021, с. 32–33. Формулы и ответы урока проверены выполнением в таблице, данные вымышленные.","stages":["Отвечает на два вопроса об адресе и диапазоне","Узнаёт понятия формула, функция, диапазон","Вместе с учителем копирует формулу и считает проценты","Решает задачи на копирование формулы, проценты и даты","Проходит короткий тест и говорит, что узнал"]},"en":{"summary":"A formula starts with “=”; references change when copied. Functions and ranges. Number, date and percent formats.","objectives":["Write a cell address and a range correctly","Write a formula and copy it to another cell","Calculate percents: “what part is” and “part of a number”"],"prior":"Know the data types (lesson 3.3) and can read a cell address.","env":"Spreadsheet: the ClassFlow sheet or Google Sheets. Google Docs/Sheets need a Google account and the internet (the account follows the school rules). One device per student.","source":"A. Zhunussov, Ye. Shaniyev, I. Gesen. Informatics, Grade 7, 1st ed., Almaty, 2021, pp. 32–33. The formulas and answers of the lesson were run in a sheet; the data are made up.","stages":["Answers two questions about addresses and ranges","Learns formula, function and range","Copies a formula and calculates percents with the teacher","Solves problems on copying a formula, percents and dates","Takes a short test and says what was learned"]}}$s7$::jsonb, $s7$[{"term":"formula","definition":"Формула — қолданушы жазатын теңдеу, «=» таңбасынан басталады · Формула — выражение, которое записывает пользователь, начинается с «=» · Formula — an expression a user writes, starting with “=”"},{"term":"function","definition":"Функция — кестедегі алдын ала анықталған есептеу · Функция — заранее определённое вычисление в таблице · Function — a predefined calculation in the sheet"},{"term":"range","definition":"Диапазон — ұяшықтар тобы, мысалы A1:C4 · Диапазон — группа ячеек, например A1:C4 · Range — a group of cells, e.g. A1:C4"},{"term":"relative reference","definition":"Салыстырмалы сілтеме — формуланы көшіргенде өзгереді · Относительная ссылка — меняется при копировании формулы · Relative reference — changes when the formula is copied"}]$s7$::jsonb, $s7$[{"type":"title","pageType":"slide","templateId":"title","title":"3.4 Деректер түрлері: формулалар мен пайыз","subtitle":"Информатика 7-сынып · 3-тарау · оқулық 32–33-б.","ru":{"title":"3.4 Типы данных: формулы и проценты","subtitle":"Информатика 7 класс · глава 3 · учебник, с. 32–33"},"en":{"title":"3.4 Data types: formulas and percent","subtitle":"Informatics Grade 7 · Chapter 3 · textbook pp. 32–33"},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: адрес","prompt":"Баған әріппен, жол санмен белгіленеді. «B» бағаны мен 3-жолдың қиылысы қалай аталады?","options":["B3","3B","B:3","3"],"answer":0,"explanation":"Адрес әріптен (баған) және саннан (жол) тұрады: B3.","points":1,"ru":{"title":"Повторение: адрес","prompt":"Столбцы обозначают буквами, строки числами. Как называется ячейка на пересечении столбца B и строки 3?","options":["B3","3B","B:3","3"],"explanation":"Адрес состоит из буквы (столбец) и числа (строка): B3.","notes":"5 минут. Добавьте один вопрос по типам данных прошлого урока: «5%» — какой тип?"},"en":{"title":"Review: address","prompt":"Columns are letters and rows numbers. What is the cell where column B meets row 3?","options":["B3","3B","B:3","3"],"explanation":"An address is a letter (column) plus a number (row): B3.","notes":"5 minutes. Add one question on last lesson’s data types: what type is “5%”?"},"stage":"warmup","notes":"5 минут. Алдыңғы сабақтағы деректер түрлеріне 1 сұрақ қосыңыз: «5%» қай түр?"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: диапазон","prompt":"A1-ден C4-ке дейінгі ұяшықтар тобы қалай жазылады?","options":["A1:C4","A1-C4","A1;C4","C4:A1:"],"answer":0,"explanation":"Диапазонды екі нүктемен жазамыз: A1:C4 — 3 баған × 4 жол = 12 ұяшық.","points":1,"ru":{"title":"Повторение: диапазон","prompt":"Как записывается группа ячеек от A1 до C4?","options":["A1:C4","A1-C4","A1;C4","C4:A1:"],"explanation":"Диапазон пишут через двоеточие: A1:C4 — 3 столбца × 4 строки = 12 ячеек."},"en":{"title":"Review: range","prompt":"How is the group of cells from A1 to C4 written?","options":["A1:C4","A1-C4","A1;C4","C4:A1:"],"explanation":"A range uses a colon: A1:C4 is 3 columns × 4 rows = 12 cells."},"stage":"warmup"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Формула және функция","bullets":["«=» таңбасын тергенде формула басталады. Мысалы, C1 ұяшығына =A1+B1 жазсақ, кесте A1 мен B1 қосындысын көрсетеді.","Ұяшық адресін қолмен жазудың орнына, ұяшықты тінтуірмен басуға болады.","Формула — оны қолданушы жазады, функция (мысалы, SUM) — кестеде дайын тұрады. Оларды бірге қолдануға болады."],"art":"formula","ru":{"title":"Формула и функция","bullets":["Знак «=» начинает формулу. Если в C1 записать =A1+B1, таблица покажет сумму A1 и B1.","Вместо того чтобы вводить адрес вручную, можно щёлкнуть по ячейке мышью.","Формулу пишет пользователь, а функция (например, SUM) уже готова в таблице. Их можно использовать вместе."]},"en":{"title":"Formula and function","bullets":["Typing “=” starts a formula. =A1+B1 in C1 shows the sum of A1 and B1.","Instead of typing an address you can click the cell.","A formula is written by the user, a function (e.g. SUM) is built in. They can be used together."]},"stage":"together","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Формуланы көшіру","bullets":["Формуланы бір ұяшықтан басқасына көшірсек (Ctrl+C, Ctrl+V), кесте оны жаңа орынға қарай өзгертеді.","Мысалы, A4-тегі =A1*(A2+A3) формуласын B4-ке көшірсек, ол =B1*(B2+B3) болады.","Санды енгізгенде тек цифрларды, үтірді және минус (плюс) белгісін қолдан — басқа таңба болмасын."],"art":"copy","ru":{"title":"Копирование формулы","bullets":["Если скопировать формулу из одной ячейки в другую (Ctrl+C, Ctrl+V), таблица изменит её под новое место.","Например, формула =A1*(A2+A3) из A4 при копировании в B4 станет =B1*(B2+B3).","Числа вводи только цифрами, запятой и знаком минус (плюс) — никаких других символов."]},"en":{"title":"Copying a formula","bullets":["When you copy a formula from one cell to another (Ctrl+C, Ctrl+V), the sheet adjusts it for the new place.","For example, =A1*(A2+A3) copied from A4 to B4 becomes =B1*(B2+B3).","Type numbers with digits, a decimal comma and a minus (plus) sign only — no other symbols."]},"stage":"together","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Мысал: пайыз","bullets":["25-тің 80-ге қатынасы неше пайыз? B3-ті B2-ге бөл: =B3/B2 — 0.3125. Percent түрін қойсаң, 31.25% көрінеді.","80-нің 30%-ын тап: =B2*30%. Мұнда 100-ге бөлу мен көбейту қажет емес!","Күндер: екі күннің айырмасы — күн саны. Күн ұяшықтарын Date түрінде жаз."],"demoSheet":{"rows":6,"cols":3,"cells":{"A1":"Көрсеткіш","B1":"Мәні","A2":"Барлығы","B2":"80","A3":"Бөлігі","B3":"25","A4":"Қатынасы, %","A5":"80-нің 30%-ы"},"fmt":{"A1":{"b":1,"bg":"#dbeafe"},"B1":{"b":1,"bg":"#dbeafe"}}},"notes":"10 минут. B4 = =B3/B2 (0.3125), B5 = =B2*30% (24). Percent түрін қосып-өшіріп, мәні өзгермей, тек көрінісі өзгеретінін көрсетіңіз. Жиі қате: пайызды 100-ге көбейтіп, содан соң Percent түрін қою (3125% шығады).","ru":{"title":"Пример: проценты","bullets":["Сколько процентов составляет 25 от 80? Раздели B3 на B2: =B3/B2 — 0.3125. В формате Percent будет 31.25%.","Найди 30% от 80: =B2*30%. Делить и умножать на 100 не нужно!","Даты: разность двух дат — число дней. Записывай даты в формате Date."],"demoSheet":{"rows":6,"cols":3,"cells":{"A1":"Показатель","B1":"Значение","A2":"Всего","B2":"80","A3":"Часть","B3":"25","A4":"Доля, %","A5":"30% от 80"},"fmt":{"A1":{"b":1,"bg":"#dbeafe"},"B1":{"b":1,"bg":"#dbeafe"}}},"notes":"10 минут. B4 = =B3/B2 (0.3125), B5 = =B2*30% (24). Включайте и выключайте Percent: значение не меняется, меняется только вид. Частая ошибка: умножить на 100 и ещё поставить Percent (получится 3125%)."},"en":{"title":"Example: percent","bullets":["What percent is 25 of 80? Divide B3 by B2: =B3/B2 gives 0.3125. In Percent format it shows 31.25%.","Find 30% of 80: =B2*30%. No dividing or multiplying by 100!","Dates: the difference of two dates is a number of days. Keep the date cells in Date format."],"demoSheet":{"rows":6,"cols":3,"cells":{"A1":"Item","B1":"Value","A2":"Total","B2":"80","A3":"Part","B3":"25","A4":"Share, %","A5":"30% of 80"},"fmt":{"A1":{"b":1,"bg":"#dbeafe"},"B1":{"b":1,"bg":"#dbeafe"}}},"notes":"10 minutes. B4 = =B3/B2 (0.3125), B5 = =B2*30% (24). Toggle Percent: the value stays, only the look changes. Common slip: multiplying by 100 and then also applying Percent (gives 3125%)."},"stage":"example"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Практика 1: формуланы көшіру","prompt":"Кестедегі сандарды енгіз, A4 ұяшығына формула жаз да, оны B4-ке көшір. Екі нәтижені салыстыр.","points":5,"picture":"lec/inf8-g7-copy-kk.svg","pictureAlt":"A1:A3 ұяшықтарында 3, 3, 7; B1:B3 ұяшықтарында 5, 8, 3; A4 және B4 бос","sheet":{"rows":14,"cols":8},"criteria":[{"id":"c1","text":"Сандар енгізілген: A1 = 3 және B3 = 3","cell":"B3","points":1,"accept":["3"]},{"id":"c2","text":"A4 — =A1*(A2+A3) формуласы","cell":"A4","points":2,"formula":true,"accept":["30"]},{"id":"c3","text":"B4 — формула көшірілген (нәтиже B бағанына сәйкес)","cell":"B4","points":2,"formula":true,"accept":["55"]}],"steps":["Көмек: A4-ке =A1*(A2+A3) жаз; жақшаны ұмытпа.","A4-ті белгіле, Ctrl+C бас, B4-ті белгіле, Ctrl+V бас. B4-тің формуласына қара."],"notes":"Күтілетін нәтиже: A4 = 3 × (3 + 7) = 30; B4 = 5 × (8 + 3) = 55. Формуланы көшіргенде A→B болып, B4 = B1*(B2+B3) шығады. Оқушылар айырмашылықты өздері тұжырымдасын: «баған әрпі бір қадамға ауысты».","ru":{"title":"Практика 1: копирование формулы","prompt":"Введи числа из таблицы, запиши формулу в A4 и скопируй её в B4. Сравни два результата.","picture":"lec/inf8-g7-copy-ru.svg","pictureAlt":"В A1:A3 числа 3, 3, 7; в B1:B3 числа 5, 8, 3; A4 и B4 пустые","criteria":[{"id":"c1","text":"Числа введены: A1 = 3 и B3 = 3","cell":"B3","points":1},{"id":"c2","text":"A4 — формула =A1*(A2+A3)","cell":"A4","points":2,"formula":true},{"id":"c3","text":"B4 — формула скопирована (результат по столбцу B)","cell":"B4","points":2,"formula":true}],"steps":["Подсказка: в A4 запиши =A1*(A2+A3); не забудь скобки.","Выдели A4, нажми Ctrl+C, выдели B4, нажми Ctrl+V. Посмотри формулу в B4."],"notes":"Ожидаемый результат: A4 = 3 × (3 + 7) = 30; B4 = 5 × (8 + 3) = 55. При копировании A→B, получается B4 = B1*(B2+B3). Пусть ученики сами скажут: «буква столбца сдвинулась на один шаг»."},"en":{"title":"Practice 1: copying a formula","prompt":"Enter the numbers from the table, write a formula in A4 and copy it to B4. Compare the two results.","picture":"lec/inf8-g7-copy-en.svg","pictureAlt":"A1:A3 hold 3, 3, 7; B1:B3 hold 5, 8, 3; A4 and B4 are empty","criteria":[{"id":"c1","text":"Numbers entered: A1 = 3 and B3 = 3","cell":"B3","points":1},{"id":"c2","text":"A4 — the formula =A1*(A2+A3)","cell":"A4","points":2,"formula":true},{"id":"c3","text":"B4 — the formula copied (result from column B)","cell":"B4","points":2,"formula":true}],"steps":["Hint: type =A1*(A2+A3) in A4; do not forget the brackets.","Select A4, press Ctrl+C, select B4, press Ctrl+V. Look at the formula in B4."],"notes":"Expected: A4 = 3 × (3 + 7) = 30; B4 = 5 × (8 + 3) = 55. Copying shifts A→B, so B4 = B1*(B2+B3). Let students say it themselves: “the column letter moved one step”."},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Практика 2: пайыз есебі","prompt":"Кестедегі сандарды енгізіп, қатынасты және берілген сомадан пайызды есепте. Нәтижені Percent түрінде көрсетуге болады.","points":7,"picture":"lec/inf8-g7-pct-kk.svg","pictureAlt":"Барлық ақша 2000, тамаққа 800; үлес, 15% сома және қалған ақша бос","sheet":{"rows":14,"cols":8},"criteria":[{"id":"c1","text":"Деректер енгізілген: B2 = 2000 және B3 = 800","cell":"B3","points":1,"accept":["800"]},{"id":"c2","text":"B4 — тамақтың үлесі (бөлу, 0.4 немесе 40%)","cell":"B4","points":2,"formula":true,"accept":["0.4","40%","40"]},{"id":"c3","text":"B5 — 2000-нің 15%-ы (=B2*15%)","cell":"B5","points":2,"formula":true,"accept":["300"]},{"id":"c4","text":"★ B6 — қалған ақша","cell":"B6","points":2,"formula":true,"accept":["900"]}],"steps":["Көмек: үлес = бөлігі / барлығы, яғни =B3/B2.","15% табу үшін =B2*15% жаз; 100-ге көбейтіп-бөлудің қажеті жоқ."],"notes":"Күтілетін нәтиже: B4 = 0.4 (40%); B5 = 300; ★ B6 = 2000 − 800 − 300 = 900. B4-ті Percent түрінде көрсетсе де, мәні 0.4 болып қалады — сондықтан 0.4 және 40% екеуі де қабылданады.","ru":{"title":"Практика 2: задача на проценты","prompt":"Введи числа из таблицы и посчитай долю и процент от заданной суммы. Результат можно показать в формате Percent.","picture":"lec/inf8-g7-pct-ru.svg","pictureAlt":"Всего 2000, на еду 800; доля, 15% и остаток пустые","criteria":[{"id":"c1","text":"Данные введены: B2 = 2000 и B3 = 800","cell":"B3","points":1},{"id":"c2","text":"B4 — доля еды (деление, 0.4 или 40%)","cell":"B4","points":2,"formula":true},{"id":"c3","text":"B5 — 15% от 2000 (=B2*15%)","cell":"B5","points":2,"formula":true},{"id":"c4","text":"★ B6 — остаток денег","cell":"B6","points":2,"formula":true}],"steps":["Подсказка: доля = часть / целое, то есть =B3/B2.","Чтобы найти 15%, запиши =B2*15%; умножать и делить на 100 не нужно."],"notes":"Ожидаемый результат: B4 = 0.4 (40%); B5 = 300; ★ B6 = 2000 − 800 − 300 = 900. В формате Percent значение остаётся 0.4, поэтому принимаются и 0.4, и 40%."},"en":{"title":"Practice 2: percent problem","prompt":"Enter the numbers from the table and calculate the share and a percentage of the given amount. The result may be shown in Percent format.","picture":"lec/inf8-g7-pct-en.svg","pictureAlt":"All money 2000, food 800; share, 15% and what is left are empty","criteria":[{"id":"c1","text":"Data entered: B2 = 2000 and B3 = 800","cell":"B3","points":1},{"id":"c2","text":"B4 — the food share (division, 0.4 or 40%)","cell":"B4","points":2,"formula":true},{"id":"c3","text":"B5 — 15% of 2000 (=B2*15%)","cell":"B5","points":2,"formula":true},{"id":"c4","text":"★ B6 — the money that is left","cell":"B6","points":2,"formula":true}],"steps":["Hint: share = part / whole, i.e. =B3/B2.","To find 15%, type =B2*15%; no need to multiply or divide by 100."],"notes":"Expected: B4 = 0.4 (40%); B5 = 300; ★ B6 = 2000 − 800 − 300 = 900. In Percent format the value stays 0.4, so both 0.4 and 40% are accepted."},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Практика 3: күн есебі","prompt":"Кестеде 01.01.2027 және 01.03.2027 күндері Date түрінде жазылған. Олардың айырмасы (=B2-B1) неше күн?","accept":["59"],"points":2,"notes":"Қаңтар 31 күн + ақпан 28 күн (2027 жыл кәбісе емес) = 59. Оқушылар өздері тексеріп көрсін: кестеде күндерді енгізіп, айырмасын алсын.","ru":{"title":"Практика 3: задача на даты","prompt":"В таблице даты 01.01.2027 и 01.03.2027 записаны в формате Date. Сколько дней между ними (=B2-B1)?","notes":"Январь 31 день + февраль 28 дней (2027 год не високосный) = 59. Пусть проверят в таблице: введут даты и вычтут."},"en":{"title":"Practice 3: dates","prompt":"A sheet holds the dates 01.01.2027 and 01.03.2027 in Date format. How many days apart are they (=B2-B1)?","notes":"January 31 days + February 28 days (2027 is not a leap year) = 59. Let them check it in a sheet: type the dates and subtract."},"stage":"practice"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Формуланы көшіру","prompt":"C2-дегі =A2+B2 формуласын C3-ке көшірсек, қандай формула шығады?","options":["=A3+B3","=A2+B2","=C2+C3","=A4+B4"],"answer":0,"explanation":"Төмен бір жолға ауысқан соң, жол нөмірі де бір қадамға артады: 2 → 3.","points":1,"ru":{"title":"Копирование формулы","prompt":"Какой станет формула =A2+B2 из C2 при копировании в C3?","options":["=A3+B3","=A2+B2","=C2+C3","=A4+B4"],"explanation":"При сдвиге на одну строку вниз номер строки тоже растёт на единицу: 2 → 3."},"en":{"title":"Copying a formula","prompt":"What does =A2+B2 in C2 become when copied to C3?","options":["=A3+B3","=A2+B2","=C2+C3","=A4+B4"],"explanation":"Moving one row down, the row number goes up by one: 2 → 3."},"stage":"check"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Пайыз","prompt":"80-нің 30%-ын табу үшін қандай формула дұрыс?","options":["=80*30%","=80*30/100*100","=80/30","=80+30%"],"answer":0,"explanation":"Пайызды санға көбейту жеткілікті: 80 × 30% = 24.","points":1,"ru":{"title":"Процент","prompt":"Какая формула верна для 30% от 80?","options":["=80*30%","=80*30/100*100","=80/30","=80+30%"],"explanation":"Достаточно умножить число на процент: 80 × 30% = 24."},"en":{"title":"Percent","prompt":"Which formula finds 30% of 80?","options":["=80*30%","=80*30/100*100","=80/30","=80+30%"],"explanation":"It is enough to multiply by the percent: 80 × 30% = 24."},"stage":"check"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"check","title":"Қорытынды: бүгін не үйрендім?","bullets":["Бүгін мен … үйрендім (өз сөзіңмен жалғастыр).","Ең қызықты бөлігі: …","Маған әлі түсініксіз: …"],"ru":{"title":"Итог: что я узнал сегодня?","bullets":["Сегодня я научился … (продолжи своими словами).","Самое интересное: …","Мне пока непонятно: …"],"notes":"Ученики дописывают три предложения в тетрадь, 2–3 ученика читают вслух. Ответы «непонятно» разберите в начале следующего урока."},"en":{"title":"Wrap-up: what did I learn today?","bullets":["Today I learned … (finish in your own words).","The most interesting part: …","I still do not understand: …"],"notes":"Students finish three sentences in a notebook; 2–3 read aloud. Revisit the “do not understand” answers at the start of the next lesson."},"stage":"check","notes":"Оқушылар үш сөйлемді дәптерге жазады, 2–3 оқушы дауыстап оқиды. «Түсініксіз» жауаптарын келесі сабақтың басында қайталаңыз.","design":"lab"}]$s7$::jsonb),
    ($s7$3.5 Шартты пішімдеу$s7$, $s7$Информатика$s7$, 4, $s7${"summary":"Шарт орындалса, ұяшықтың түсі өздігінен өзгереді: бір түсті ереже, түс шкаласы, өз формуласы.","objectives":["Шартты пішімдеу не үшін керегін түсіндіру","Google Sheets-те бір түсті ереже жасау","Өз формуласымен бүкіл жолды бояу"],"grade":7,"duration":"45 минут","prior":"Ұяшықты бояуды, деректер түрлерін біледі (3.3–3.4 сабақтар).","env":"Кесте: ClassFlow кестесі немесе Google Sheets. Google Docs/Sheets үшін оқушыда Google аккаунты және интернет болуы керек (аккаунт мектеп ережесіне сай ашылады). Әр оқушыға бір құрылғы.","source":"A. Zhunussov, Ye. Shaniyev, I. Gesen. Informatics, Grade 7, 1st ed., Almaty, 2021, 34–35 беттер. Сабақтағы формулалар мен жауаптар кестеде орындалып тексерілген, деректер ойдан шығарылған.","stages":[{"k":"warmup","min":5,"do":"Не нәрсені дәптерде ерекшелейтіні туралы сұраққа жауап береді"},{"k":"together","min":8,"do":"Шартты пішімдеудің қадамдарын үйренеді"},{"k":"example","min":10,"do":"Мұғаліммен бірге 80%-дан төмен балдарды қызыл түске бояйды"},{"k":"practice","min":15,"do":"Өз кестесінде ереже жасап, екі есеп шығарады"},{"k":"check","min":7,"do":"Қысқа тест тапсырып, не үйренгенін айтады"}],"ru":{"summary":"Если условие выполняется, цвет ячейки меняется сам: правило одного цвета, цветовая шкала, своя формула.","objectives":["Объяснять, зачем нужно условное форматирование","Создавать правило одного цвета в Google Sheets","Окрашивать всю строку собственной формулой"],"prior":"Умеют закрашивать ячейки, знают типы данных (уроки 3.3–3.4).","env":"Таблица: ClassFlow или Google Sheets. Для Google Docs/Sheets нужны аккаунт Google и интернет (аккаунт — по правилам школы). Каждому ученику по устройству.","source":"A. Zhunussov, Ye. Shaniyev, I. Gesen. Informatics, Grade 7, 1st ed., Almaty, 2021, с. 34–35. Формулы и ответы урока проверены выполнением в таблице, данные вымышленные.","stages":["Отвечает на вопрос, как выделяет важное в тетради","Узнаёт шаги условного форматирования","Вместе с учителем красит баллы ниже 80% в красный","Создаёт правило в своей таблице и решает две задачи","Проходит короткий тест и говорит, что узнал"]},"en":{"summary":"If a condition holds, the cell colour changes by itself: single colour rule, colour scale, custom formula.","objectives":["Explain what conditional formatting is for","Create a single colour rule in Google Sheets","Colour a whole row with a custom formula"],"prior":"Can fill cells and know the data types (lessons 3.3–3.4).","env":"Spreadsheet: the ClassFlow sheet or Google Sheets. Google Docs/Sheets need a Google account and the internet (the account follows the school rules). One device per student.","source":"A. Zhunussov, Ye. Shaniyev, I. Gesen. Informatics, Grade 7, 1st ed., Almaty, 2021, pp. 34–35. The formulas and answers of the lesson were run in a sheet; the data are made up.","stages":["Answers how they highlight important things in a notebook","Learns the steps of conditional formatting","Colours scores below 80% red with the teacher","Creates a rule in their own sheet and solves two problems","Takes a short test and says what was learned"]}}$s7$::jsonb, $s7$[{"term":"conditional formatting","definition":"Шартты пішімдеу — шарт орындалса, ұяшық пішімі өздігінен өзгереді · Условное форматирование — формат ячейки меняется сам, если выполняется условие · Conditional formatting — the cell format changes by itself when a condition holds"},{"term":"rule","definition":"Ереже — қандай шартта қандай пішім қолданылатынын көрсетеді · Правило — задаёт, при каком условии какой формат применить · Rule — says which format to apply under which condition"},{"term":"color scale","definition":"Түс шкаласы — мәнге қарай түс біртіндеп өзгереді · Цветовая шкала — цвет плавно меняется в зависимости от значения · Color scale — the colour changes smoothly with the value"}]$s7$::jsonb, $s7$[{"type":"title","pageType":"slide","templateId":"title","title":"3.5 Шартты пішімдеу","subtitle":"Информатика 7-сынып · 3-тарау · оқулық 34–35-б.","ru":{"title":"3.5 Условное форматирование","subtitle":"Информатика 7 класс · глава 3 · учебник, с. 34–35"},"en":{"title":"3.5 Conditional formatting","subtitle":"Informatics Grade 7 · Chapter 3 · textbook pp. 34–35"},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: пішім","prompt":"Ұяшық түсін қолмен өзгертсең, оның мәні өзгере ме?","options":["Жоқ, тек сыртқы түрі өзгереді","Иә, мән жоғалады","Иә, ол 0 болады","Ұяшық жойылады"],"answer":0,"explanation":"Пішім мәнді өзгертпейді, тек оның көрінісін өзгертеді.","points":1,"ru":{"title":"Повторение: формат","prompt":"Если закрасить ячейку вручную, изменится ли её значение?","options":["Нет, меняется только вид","Да, значение пропадёт","Да, станет 0","Ячейка удалится"],"explanation":"Формат не меняет значение, а только его вид.","notes":"5 минут. Спросите: «Как выделяешь важное в тетради — маркер, подчёркивание?» Ответы — подводка к теме."},"en":{"title":"Review: format","prompt":"If you colour a cell by hand, does its value change?","options":["No, only the look changes","Yes, the value is lost","Yes, it becomes 0","The cell is deleted"],"explanation":"Formatting does not change the value, only how it looks.","notes":"5 minutes. Ask: “How do you mark important things in a notebook — marker, underline?” It leads into the topic."},"stage":"warmup","notes":"5 минут. Сұрақ: «Дәптерде маңызды нәрсені қалай ерекшелейсің — маркер, асты сызу?» Жауаптар шартты пішімдеуге кіріспе."},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: сан түрі","prompt":"0.8 санын 80% деп көрсететін түр қайсы?","options":["Percent","Date","Time","Plain text"],"answer":0,"explanation":"Percent түрі 0.8 санын 80% түрінде көрсетеді; мәні 0.8 болып қалады.","points":1,"ru":{"title":"Повторение: тип числа","prompt":"Какой тип показывает 0.8 как 80%?","options":["Percent","Date","Time","Plain text"],"explanation":"Тип Percent показывает 0.8 как 80%; значение остаётся 0.8."},"en":{"title":"Review: number type","prompt":"Which type shows 0.8 as 80%?","options":["Percent","Date","Time","Plain text"],"explanation":"Percent shows 0.8 as 80%; the value stays 0.8."},"stage":"warmup"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Шартты пішімдеу деген не?","bullets":["Ұяшықтардың, жолдардың немесе бағандардың мәтіні мен фоны, егер белгілі шарт орындалса, өздігінен өзгереді.","Мысалы, мұғалім емтихан нәтижелерінде 80%-дан төмен балды қызылмен ерекшелейді.","Мән өзгерсе, түс те өздігінен өзгереді: қайта бояудың қажеті жоқ."],"art":"ifflow","ru":{"title":"Что такое условное форматирование?","bullets":["Текст и фон ячеек, строк или столбцов меняются сами, если выполняется определённое условие.","Например, учитель выделяет красным результаты экзамена ниже 80%.","Если значение изменится, цвет изменится сам: перекрашивать не нужно."]},"en":{"title":"What is conditional formatting?","bullets":["The text and background of cells, rows or columns change by themselves when a certain condition is met.","For example, a teacher can colour test scores below 80% red.","If a value changes, the colour follows it: no need to recolour."]},"stage":"together","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Ереже жасау қадамдары","bullets":["Google Sheets-те кестені аш, ереже қолданылатын ұяшықтарды белгіле.","Format → Conditional formatting. Оң жақта панель ашылады.","«Format cells if» тізімінен шартты таңда (мысалы, Less than), мәнін жаз, «Fill» түсін таңда, Done бас."],"ru":{"title":"Шаги создания правила","bullets":["Открой таблицу в Google Sheets и выдели ячейки, к которым применится правило.","Format → Conditional formatting. Справа откроется панель.","В списке «Format cells if» выбери условие (например, Less than), впиши значение, выбери цвет «Fill», нажми Done."],"notes":"8 минут. Color scale — второй вид: выбирают два цвета для наименьшего и наибольшего значений, промежуточные окрашиваются плавно. Правило удаляют кнопкой Remove при наведении на него."},"en":{"title":"Steps of making a rule","bullets":["Open the sheet in Google Sheets and select the cells for the rule.","Format → Conditional formatting. A panel opens on the right.","Under “Format cells if” pick a condition (e.g. Less than), type a value, pick a “Fill” colour, click Done."],"notes":"8 minutes. A color scale is the second kind: two colours for the smallest and largest value, the rest blend. Remove a rule with the Remove button when pointing at it."},"stage":"together","notes":"8 минут. Түс шкаласы (Color scale) — екінші түрі: ең кіші мен ең үлкен мәнге екі түс таңдалады, аралық мән өтпелі түспен боялады. Ережені өшіру үшін оның үстіне апарып Remove бас.","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Мысал: 80%-дан төмен балдар","bullets":["B2:B7 баллдарын белгіле.","Format → Conditional formatting → «Less than» → 0.8 → Fill: қызыл → Done.","Қызыл болған ұяшықтарды санап көр. Бір баллды 0.9 деп өзгерт: қызыл түс жоғалады."],"demoSheet":{"rows":7,"cols":2,"cells":{"A1":"Оқушы","B1":"Нәтиже","A2":"Алмас","B2":"92%","A3":"Айгерім","B3":"78%","A4":"Нұрлан","B4":"65%","A5":"Дана","B5":"80%","A6":"Ербол","B6":"79%","A7":"Мөлдір","B7":"85%"},"fmt":{"A1":{"b":1,"bg":"#dbeafe"},"B1":{"b":1,"bg":"#dbeafe"},"B3":{"bg":"#fecaca"},"B4":{"bg":"#fecaca"},"B6":{"bg":"#fecaca"}}},"notes":"10 минут. Күтілетін нәтиже: қызыл түске 78%, 65%, 79% боялады — 3 ұяшық. 80% қызыл емес, себебі «Less than» дәл 80%-ды қамтымайды. Оқушылар өздері «Less than or equal to» таңдап көрсін.","ru":{"title":"Пример: баллы ниже 80%","bullets":["Выдели баллы B2:B7.","Format → Conditional formatting → «Less than» → 0.8 → Fill: красный → Done.","Посчитай закрашенные ячейки. Измени один балл на 0.9: красный цвет исчезнет."],"demoSheet":{"rows":7,"cols":2,"cells":{"A1":"Ученик","B1":"Результат","A2":"Алмас","B2":"92%","A3":"Айгерим","B3":"78%","A4":"Нурлан","B4":"65%","A5":"Дана","B5":"80%","A6":"Ербол","B6":"79%","A7":"Молдир","B7":"85%"},"fmt":{"A1":{"b":1,"bg":"#dbeafe"},"B1":{"b":1,"bg":"#dbeafe"},"B3":{"bg":"#fecaca"},"B4":{"bg":"#fecaca"},"B6":{"bg":"#fecaca"}}},"notes":"10 минут. Ожидаемый результат: красными станут 78%, 65%, 79% — 3 ячейки. 80% не красный, ведь «Less than» не включает ровно 80%. Пусть сами попробуют «Less than or equal to»."},"en":{"title":"Example: scores below 80%","bullets":["Select the scores B2:B7.","Format → Conditional formatting → “Less than” → 0.8 → Fill: red → Done.","Count the coloured cells. Change one score to 0.9: the red disappears."],"demoSheet":{"rows":7,"cols":2,"cells":{"A1":"Student","B1":"Result","A2":"Almas","B2":"92%","A3":"Aigerim","B3":"78%","A4":"Nurlan","B4":"65%","A5":"Dana","B5":"80%","A6":"Erbol","B6":"79%","A7":"Moldir","B7":"85%"},"fmt":{"A1":{"b":1,"bg":"#dbeafe"},"B1":{"b":1,"bg":"#dbeafe"},"B3":{"bg":"#fecaca"},"B4":{"bg":"#fecaca"},"B6":{"bg":"#fecaca"}}},"notes":"10 minutes. Expected: 78%, 65% and 79% turn red — 3 cells. 80% stays plain because “Less than” does not include exactly 80%. Let students try “Less than or equal to”."},"stage":"example"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Өз формуласымен бояу","bullets":["«Format cells if» тізімінен «Custom formula is» таңда. Формула «=» таңбасынан басталады.","Егер B бағанында «Yes» болса, бүкіл жолды жасыл ет: =$B1=\"Yes\".","Ережелер тізімдегі ретімен тексеріледі: бірінші рас ереже ұяшық пішімін анықтайды."],"ru":{"title":"Окраска своей формулой","bullets":["В списке «Format cells if» выбери «Custom formula is». Формула начинается с «=».","Чтобы красить всю строку зелёным, когда в столбце B стоит «Yes», запиши =$B1=\"Yes\".","Правила проверяются по порядку списка: первое выполнившееся определяет формат ячейки."]},"en":{"title":"Colouring with a custom formula","bullets":["Under “Format cells if” pick “Custom formula is”. The formula starts with “=”.","To make the whole row green when column B says “Yes”, write =$B1=\"Yes\".","Rules are checked in list order: the first true one decides the format."]},"stage":"example","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"practice","title":"Практика 1 және 2: ережелер","bullets":["Нысанаға жеткені үшін 15000-нан артық адамдар жасыл, 15000-нан кемі қызыл, дәл 15000 — сары түспен көрсетілсін.","Оқушының нәтижесі 80%-дан төмен болса, бүкіл жол боялсын (Custom formula).","Дайын кестені мұғалімге көрсет. Төмендегі екі есеп автоматты тексеріледі."],"ru":{"title":"Практика 1 и 2: правила","bullets":["Люди с результатом больше 15000 — зелёные, меньше 15000 — красные, ровно 15000 — жёлтые.","Если результат ученика ниже 80%, окрасить всю строку (Custom formula).","Покажи готовую таблицу учителю. Две задачи ниже проверяются автоматически."],"notes":"15 минут. Правило проверяйте на экране: верный диапазон, условие, цвет. Измените значения — цвет должен поменяться."},"en":{"title":"Practice 1 and 2: rules","bullets":["Anyone above 15000 in green, below 15000 in red, exactly 15000 in yellow.","If a student’s score is below 80%, colour the entire row (Custom formula).","Show the finished sheet to the teacher. The two problems below are marked automatically."],"notes":"15 minutes. Check the rule on screen: right range, condition, colour. Change values — the colour must follow."},"stage":"practice","notes":"15 минут. Ереже жасалғанын мұғалім экраннан тексереді: дұрыс диапазон, шарт, түс. Мәндерді өзгертіп көріңіз — түс өзгеруі керек.","design":"lab"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Есеп: қанша ұяшық қызыл?","prompt":"Нәтижелер: 92, 78, 65, 80, 79, 85. Ереже: «Less than 80» → қызыл. Неше ұяшық қызыл болады?","accept":["3"],"points":2,"notes":"78, 65, 79 — үшеуі; 80 қызыл болмайды (шарт қатаң «аз»).","ru":{"title":"Задача: сколько красных?","prompt":"Результаты: 92, 78, 65, 80, 79, 85. Правило: «Less than 80» → красный. Сколько ячеек станут красными?","notes":"78, 65, 79 — три; 80 красным не станет (условие строго «меньше»)."},"en":{"title":"Problem: how many red cells?","prompt":"Scores: 92, 78, 65, 80, 79, 85. Rule: “Less than 80” → red. How many cells turn red?","notes":"78, 65, 79 are three; 80 stays plain (the condition is strictly “less”)."},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Есеп: сары ұяшықтар","prompt":"Нысанаға жету: 14800, 15000, 17200, 9000, 15000, 21000. Ереже: 15000-нан артық — жасыл, кем — қызыл, тең — сары. Неше ұяшық сары?","accept":["2"],"points":2,"ru":{"title":"Задача: жёлтые ячейки","prompt":"Выполнение: 14800, 15000, 17200, 9000, 15000, 21000. Правило: больше 15000 — зелёный, меньше — красный, равно — жёлтый. Сколько ячеек жёлтые?"},"en":{"title":"Problem: yellow cells","prompt":"Targets reached: 14800, 15000, 17200, 9000, 15000, 21000. Rule: above 15000 green, below red, equal yellow. How many cells are yellow?"},"stage":"practice"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Ереже қайда?","prompt":"Шартты пішімдеу қай мәзір арқылы ашылады?","options":["Format → Conditional formatting","File → Print","Insert → Chart","Data → Sort"],"answer":0,"explanation":"Шартты пішімдеу — Format мәзірінде.","points":1,"ru":{"title":"Где правило?","prompt":"Через какое меню открывается условное форматирование?","options":["Format → Conditional formatting","File → Print","Insert → Chart","Data → Sort"],"explanation":"Условное форматирование находится в меню Format."},"en":{"title":"Where is the rule?","prompt":"Which menu opens conditional formatting?","options":["Format → Conditional formatting","File → Print","Insert → Chart","Data → Sort"],"explanation":"Conditional formatting is in the Format menu."},"stage":"check"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Түс шкаласы","prompt":"Single color мен Color scale айырмашылығы қандай?","options":["Single color — шарт орындалса бір түс; Color scale — мәнге қарай түс біртіндеп өзгереді","Бір-бірінен еш айырмашылығы жоқ","Single color тек мәтінді бояйды","Color scale тек жолдарды ғана бояйды"],"answer":0,"explanation":"Бір түсті ереже шарт орындалғанда ғана бояйды, ал шкала барлық ұяшықты мәнге қарай бояйды.","points":1,"ru":{"title":"Цветовая шкала","prompt":"Чем отличаются Single color и Color scale?","options":["Single color — один цвет, если условие выполнено; Color scale — цвет плавно меняется по значению","Различий нет","Single color красит только текст","Color scale красит только строки"],"explanation":"Правило одного цвета красит только при выполнении условия, а шкала красит все ячейки по значению."},"en":{"title":"Colour scale","prompt":"How do Single color and Color scale differ?","options":["Single color gives one colour when a condition holds; Color scale shades colours by value","There is no difference","Single color colours text only","Color scale colours rows only"],"explanation":"A single-colour rule paints only when the condition holds, a scale paints every cell by value."},"stage":"check"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"check","title":"Қорытынды: бүгін не үйрендім?","bullets":["Бүгін мен … үйрендім (өз сөзіңмен жалғастыр).","Ең қызықты бөлігі: …","Маған әлі түсініксіз: …"],"ru":{"title":"Итог: что я узнал сегодня?","bullets":["Сегодня я научился … (продолжи своими словами).","Самое интересное: …","Мне пока непонятно: …"],"notes":"Ученики дописывают три предложения в тетрадь, 2–3 ученика читают вслух. Ответы «непонятно» разберите в начале следующего урока."},"en":{"title":"Wrap-up: what did I learn today?","bullets":["Today I learned … (finish in your own words).","The most interesting part: …","I still do not understand: …"],"notes":"Students finish three sentences in a notebook; 2–3 read aloud. Revisit the “do not understand” answers at the start of the next lesson."},"stage":"check","notes":"Оқушылар үш сөйлемді дәптерге жазады, 2–3 оқушы дауыстап оқиды. «Түсініксіз» жауаптарын келесі сабақтың басында қайталаңыз.","design":"lab"}]$s7$::jsonb),
    ($s7$3.6 Деректерді графиктік түрде көрсету$s7$, $s7$Информатика$s7$, 5, $s7${"summary":"Диаграмма — деректердің графиктік көрінісі: бағанды, сызықтық және дөңгелек. Қайсысын қашан таңдау және Insert → Chart.","objectives":["Бағанды, сызықтық және дөңгелек диаграммалардың айырмасын түсіндіру","Берілген деректерге сай диаграмма түрін таңдау","Кесте негізінде диаграмма салу"],"grade":7,"duration":"45 минут","prior":"Кесте жасай алады, пайыз есептей алады (3.3–3.5 сабақтар).","env":"Кесте: ClassFlow кестесі немесе Google Sheets. Google Docs/Sheets үшін оқушыда Google аккаунты және интернет болуы керек (аккаунт мектеп ережесіне сай ашылады). Әр оқушыға бір құрылғы.","source":"A. Zhunussov, Ye. Shaniyev, I. Gesen. Informatics, Grade 7, 1st ed., Almaty, 2021, 36–37 беттер. Сабақтағы формулалар мен жауаптар кестеде орындалып тексерілген, деректер ойдан шығарылған.","stages":[{"k":"warmup","min":5,"do":"Шығындарды суретпен көрсетудің пайдасы туралы екі сұраққа жауап береді"},{"k":"together","min":8,"do":"Үш диаграмма түрін және оларды таңдау ережесін үйренеді"},{"k":"example","min":10,"do":"Мұғаліммен бірге ақша шығыны кестесінен дөңгелек диаграмма салады"},{"k":"practice","min":15,"do":"Өз деректері бойынша диаграмма салып, екі есеп шығарады"},{"k":"check","min":7,"do":"Қысқа тест тапсырып, не үйренгенін айтады"}],"ru":{"summary":"Диаграмма — графическое представление данных: столбчатая, линейная и круговая. Какую выбрать и как вставить: Insert → Chart.","objectives":["Объяснять разницу между столбчатой, линейной и круговой диаграммами","Выбирать вид диаграммы под данные","Строить диаграмму по таблице"],"prior":"Умеют делать таблицу и считать проценты (уроки 3.3–3.5).","env":"Таблица: ClassFlow или Google Sheets. Для Google Docs/Sheets нужны аккаунт Google и интернет (аккаунт — по правилам школы). Каждому ученику по устройству.","source":"A. Zhunussov, Ye. Shaniyev, I. Gesen. Informatics, Grade 7, 1st ed., Almaty, 2021, с. 36–37. Формулы и ответы урока проверены выполнением в таблице, данные вымышленные.","stages":["Отвечает на два вопроса о пользе наглядного показа данных","Узнаёт три вида диаграмм и правило выбора","Вместе с учителем строит круговую диаграмму по таблице расходов","Строит диаграмму по своим данным и решает две задачи","Проходит короткий тест и говорит, что узнал"]},"en":{"summary":"A chart is a graphical view of data: bar, line and pie. Which one to choose, and Insert → Chart.","objectives":["Explain the difference between bar, line and pie charts","Choose a chart type to fit the data","Build a chart from a table"],"prior":"Can make a table and calculate percents (lessons 3.3–3.5).","env":"Spreadsheet: the ClassFlow sheet or Google Sheets. Google Docs/Sheets need a Google account and the internet (the account follows the school rules). One device per student.","source":"A. Zhunussov, Ye. Shaniyev, I. Gesen. Informatics, Grade 7, 1st ed., Almaty, 2021, pp. 36–37. The formulas and answers of the lesson were run in a sheet; the data are made up.","stages":["Answers two questions on why a picture of data helps","Learns the three chart types and how to choose","Builds a pie chart from an expenses table with the teacher","Builds a chart from own data and solves two problems","Takes a short test and says what was learned"]}}$s7$::jsonb, $s7$[{"term":"chart","definition":"Диаграмма — деректердің графиктік көрінісі · Диаграмма — графическое представление данных · Chart — a graphical representation of data"},{"term":"bar chart","definition":"Бағанды диаграмма — жеке элементтерді салыстыруға · Столбчатая диаграмма — для сравнения отдельных элементов · Bar chart — compares individual items"},{"term":"line chart","definition":"Сызықтық диаграмма — өзгеру жылдамдығын көрсетеді · Линейная диаграмма — показывает скорость изменения · Line chart — shows the rate of change"},{"term":"pie chart","definition":"Дөңгелек диаграмма — бөліктің бүтінге қатынасын пайызбен көрсетеді · Круговая диаграмма — показывает доли целого в процентах · Pie chart — shows parts of a whole as percentages"}]$s7$::jsonb, $s7$[{"type":"title","pageType":"slide","templateId":"title","title":"3.6 Деректерді графиктік түрде көрсету","subtitle":"Информатика 7-сынып · 3-тарау · оқулық 36–37-б.","ru":{"title":"3.6 Графическое представление данных","subtitle":"Информатика 7 класс · глава 3 · учебник, с. 36–37"},"en":{"title":"3.6 Graphical representation of data","subtitle":"Informatics Grade 7 · Chapter 3 · textbook pp. 36–37"},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: диапазон","prompt":"A2:E6 диапазонында неше ұяшық бар?","options":["25","10","15","30"],"answer":0,"explanation":"5 баған (A–E) × 5 жол (2–6) = 25.","points":1,"ru":{"title":"Повторение: диапазон","prompt":"Сколько ячеек в диапазоне A2:E6?","options":["25","10","15","30"],"explanation":"5 столбцов (A–E) × 5 строк (2–6) = 25.","notes":"5 минут. Этот диапазон потом выделяют для диаграммы. Спросите: «Где проще понять данные — в таблице или на диаграмме?»"},"en":{"title":"Review: range","prompt":"How many cells are in A2:E6?","options":["25","10","15","30"],"explanation":"5 columns (A–E) × 5 rows (2–6) = 25.","notes":"5 minutes. This range is later selected for the chart. Ask: “Where is data easier to grasp — in a table or on a chart?”"},"stage":"warmup","notes":"5 минут. Бұл диапазон кейін диаграмма үшін белгіленеді. Сұрақ: «Қай суретте деректі түсіну жеңіл: кестеде ме, диаграммада ма?»"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: пайыз","prompt":"2000 теңгенің 500 теңгесі неше пайыз?","options":["25%","40%","10%","50%"],"answer":0,"explanation":"500 / 2000 = 0.25 = 25%.","points":1,"ru":{"title":"Повторение: проценты","prompt":"Сколько процентов составляют 500 тенге от 2000?","options":["25%","40%","10%","50%"],"explanation":"500 / 2000 = 0.25 = 25%."},"en":{"title":"Review: percent","prompt":"What percent is 500 tenge of 2000?","options":["25%","40%","10%","50%"],"explanation":"500 / 2000 = 0.25 = 25%."},"stage":"warmup"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Диаграмманың үш түрі","bullets":["Диаграмма (график) — деректердің графиктік көрінісі.","Бағанды: жеке элементтерді салыстыр (смартфондар бағасы). Сызықтық: өзгеру жылдамдығын көрсет (аптадағы температура).","Дөңгелек: бөліктің бүтінге қатынасын пайызбен көрсет (түрлі іске кеткен уақыт)."],"art":"charts","ru":{"title":"Три вида диаграмм","bullets":["Диаграмма (график) — графическое представление данных.","Столбчатая: сравнивает отдельные элементы (цены смартфонов). Линейная: показывает скорость изменения (температура за неделю).","Круговая: показывает доли целого в процентах (время на разные занятия)."]},"en":{"title":"Three kinds of chart","bullets":["A chart (graph) is a graphical representation of data.","Bar: compare individual items (phone prices). Line: show the rate of change (temperature through the week).","Pie: show a part-to-whole relation in percent (time spent on different activities)."]},"stage":"together","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Диаграмма қалай салынады","bullets":["Кестені жаса, мысалы A1:E6 диапазонында.","Деректерді белгіле: A2:E6 (сандармен). Insert → Chart.","Оң жақтағы Chart editor-да диаграмма түрін таңда және баптауларын өзгерт."],"ru":{"title":"Как построить диаграмму","bullets":["Составь таблицу, например в диапазоне A1:E6.","Выдели данные: A2:E6 (с числами). Insert → Chart.","В Chart editor справа выбери вид диаграммы и настрой её."],"notes":"8 минут. Подводный камень: Google Sheets сам выберет вид диаграммы; ученик должен открыть «Chart type» и выбрать вид под задачу."},"en":{"title":"How to make a chart","bullets":["Make a table, for instance in the range A1:E6.","Select the data: A2:E6 (with the numbers). Insert → Chart.","In the Chart editor on the right pick the chart type and adjust it."],"notes":"8 minutes. Pitfall: Google Sheets picks a type by itself; students must open “Chart type” and choose one that fits the task."},"stage":"together","notes":"8 минут. Назар аударыңыз: Google Sheets диаграмма түрін өзі таңдайды, сондықтан оқушы «Chart type» ашып, мақсатқа сай түрді өзі таңдасын.","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Мысал: қалтадағы ақша шығыны","bullets":["A1:B5 деректерін белгіле.","Insert → Chart → Chart type: Pie chart.","Бөліктердің қосындысы 100% болуы керек: 40% + 20% + 15% + 25%. Неге бағанды емес, дөңгелек диаграмма таңдадық?"],"demoSheet":{"rows":5,"cols":2,"cells":{"A1":"Шығын","B1":"Сомасы, ₸","A2":"Тамақ","B2":"800","A3":"Көлік","B3":"400","A4":"Кітаптар","B4":"300","A5":"Ойын-сауық","B5":"500"},"fmt":{"A1":{"b":1,"bg":"#dbeafe"},"B1":{"b":1,"bg":"#dbeafe"}}},"notes":"10 минут. Жалпы сома 2000, үлестері 40%, 20%, 15%, 25%. Жауап: диаграмма «бөлік — бүтін» қатынасын көрсетеді, сондықтан дөңгелек.","ru":{"title":"Пример: расходы из карманных денег","bullets":["Выдели данные A1:B5.","Insert → Chart → Chart type: Pie chart.","Сумма долей должна быть 100%: 40% + 20% + 15% + 25%. Почему выбрали круговую, а не столбчатую?"],"demoSheet":{"rows":5,"cols":2,"cells":{"A1":"Расход","B1":"Сумма, ₸","A2":"Еда","B2":"800","A3":"Транспорт","B3":"400","A4":"Книги","B4":"300","A5":"Развлечения","B5":"500"},"fmt":{"A1":{"b":1,"bg":"#dbeafe"},"B1":{"b":1,"bg":"#dbeafe"}}},"notes":"10 минут. Общая сумма 2000, доли 40%, 20%, 15%, 25%. Ответ: диаграмма показывает «часть — целое», поэтому круговая."},"en":{"title":"Example: pocket money spending","bullets":["Select the data A1:B5.","Insert → Chart → Chart type: Pie chart.","The parts must add up to 100%: 40% + 20% + 15% + 25%. Why a pie chart rather than a bar chart?"],"demoSheet":{"rows":5,"cols":2,"cells":{"A1":"Item","B1":"Amount, ₸","A2":"Food","B2":"800","A3":"Transport","B3":"400","A4":"Books","B4":"300","A5":"Fun","B5":"500"},"fmt":{"A1":{"b":1,"bg":"#dbeafe"},"B1":{"b":1,"bg":"#dbeafe"}}},"notes":"10 minutes. Total 2000, shares 40%, 20%, 15%, 25%. Answer: the chart shows part-to-whole, so a pie."},"stage":"example"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"practice","title":"Практика: Қазақстан облыстары","bullets":["Қазақстанда 14 облыс бар. Әр облыстың ауданы (км²) туралы ақпарат тап, екі бағанды кесте жаса: облыс атауы, ауданы.","Әр облыстың ауданының үлесін көрсететін дөңгелек диаграмма сал.","Қосымша: компанияның жарты жылдағы кірісі мен шығысына, Олимпиада медальдарына лайықты диаграмма сал. Дайын жұмысты мұғалімге көрсет."],"ru":{"title":"Практика: области Казахстана","bullets":["В Казахстане 14 областей. Найди площадь каждой (км²) и сделай таблицу из двух столбцов: название, площадь.","Построй круговую диаграмму долей площади каждой области.","Дополнительно: подбери диаграмму для дохода и расхода компании за полгода и для медалей Олимпиады. Покажи работу учителю."],"notes":"15 минут. Площади областей можно взять из учебника или открытого источника. Учитель смотрит: выделен ли верный диапазон, подходит ли вид диаграммы, есть ли название. Платформа диаграммы не проверяет — автоматически только задачи ниже."},"en":{"title":"Practice: regions of Kazakhstan","bullets":["Kazakhstan has 14 regions. Find the area of each (km²) and make a two-column table: name, area.","Make a pie chart that shows each region’s share of the area.","Extra: choose a chart for a company’s half-year income and expense, and for an Olympic medal table. Show the result to the teacher."],"notes":"15 minutes. Areas can come from the textbook or an open source. The teacher checks the selected range, a suitable chart type and a title. The platform does not mark charts — only the problems below are automatic."},"stage":"practice","notes":"15 минут. Облыстар ауданын оқулықтан немесе ашық дереккөзден алуға болады. Мұғалім тексеретіні: дұрыс диапазон белгіленген бе, диаграмма түрі деректерге сай ма, атауы бар ма. Платформа диаграмманы тексермейді — төмендегі есептер ғана автоматты.","design":"lab"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Практика: бөліктердің үлесі","prompt":"Дөңгелек диаграмма үшін әр шығынның үлесін есепте: шығын / барлығы. Үлесті Percent түрінде көрсетуге болады.","points":9,"picture":"lec/inf8-g7-share-kk.svg","pictureAlt":"Төрт шығын: 800, 400, 300, 500; үлестер мен жалпы сома бос","sheet":{"rows":14,"cols":8},"criteria":[{"id":"c1","text":"Деректер енгізілген: B2 = 800 және B5 = 500","cell":"B5","points":1,"accept":["500"]},{"id":"c2","text":"B6 — жалпы шығын (SUM)","cell":"B6","points":2,"fn":"SUM","accept":["2000"]},{"id":"c3","text":"C2 — тамақтың үлесі (0.4 немесе 40%)","cell":"C2","points":2,"formula":true,"accept":["0.4","40%","40"]},{"id":"c4","text":"C5 — ойын-сауықтың үлесі (0.25 немесе 25%)","cell":"C5","points":2,"formula":true,"accept":["0.25","25%","25"]},{"id":"c5","text":"★ C6 — үлестердің қосындысы 100% (SUM)","cell":"C6","points":2,"fn":"SUM","accept":["1","100%","100"]}],"steps":["Көмек: алдымен B6-ға =SUM(B2:B5) жаз — барлығы 2000.","C2-ге =B2/B6 жаз. Басқа үлестерді өзің жаз: әрқайсысында бөлгіш B6.","★ Күрделі: C6-ға үлестердің қосындысын жаз. Дөңгелек диаграмманы A1:B5 бойынша сал."],"notes":"Күтілетін нәтиже: B6 = 2000; C2 = 0.4, C3 = 0.2, C4 = 0.15, C5 = 0.25; C6 = 1 (100%). Үлестердің қосындысы 100% болмаса, дөңгелек диаграмма «толмайды» — қайда қате екенін іздеу керек.","ru":{"title":"Практика: доли частей","prompt":"Для круговой диаграммы посчитай долю каждого расхода: расход / всего. Долю можно показать в формате Percent.","picture":"lec/inf8-g7-share-ru.svg","pictureAlt":"Четыре расхода: 800, 400, 300, 500; доли и общая сумма пустые","criteria":[{"id":"c1","text":"Данные введены: B2 = 800 и B5 = 500","cell":"B5","points":1},{"id":"c2","text":"B6 — общий расход (SUM)","cell":"B6","points":2,"fn":"SUM"},{"id":"c3","text":"C2 — доля еды (0.4 или 40%)","cell":"C2","points":2,"formula":true},{"id":"c4","text":"C5 — доля развлечений (0.25 или 25%)","cell":"C5","points":2,"formula":true},{"id":"c5","text":"★ C6 — сумма долей равна 100% (SUM)","cell":"C6","points":2,"fn":"SUM"}],"steps":["Подсказка: сначала в B6 запиши =SUM(B2:B5) — всего 2000.","В C2 запиши =B2/B6. Остальные доли запиши сам: в каждой делитель B6.","★ Сложнее: в C6 запиши сумму долей. Построй круговую диаграмму по A1:B5."],"notes":"Ожидаемый результат: B6 = 2000; C2 = 0.4, C3 = 0.2, C4 = 0.15, C5 = 0.25; C6 = 1 (100%). Если сумма долей не 100%, круг «не замкнётся» — нужно искать ошибку."},"en":{"title":"Practice: shares of parts","prompt":"For a pie chart work out each expense’s share: expense / total. You may show the share in Percent format.","picture":"lec/inf8-g7-share-en.svg","pictureAlt":"Four expenses: 800, 400, 300, 500; shares and the total are empty","criteria":[{"id":"c1","text":"Data entered: B2 = 800 and B5 = 500","cell":"B5","points":1},{"id":"c2","text":"B6 — total spending (SUM)","cell":"B6","points":2,"fn":"SUM"},{"id":"c3","text":"C2 — the food share (0.4 or 40%)","cell":"C2","points":2,"formula":true},{"id":"c4","text":"C5 — the fun share (0.25 or 25%)","cell":"C5","points":2,"formula":true},{"id":"c5","text":"★ C6 — the shares add up to 100% (SUM)","cell":"C6","points":2,"fn":"SUM"}],"steps":["Hint: first type =SUM(B2:B5) in B6 — the total is 2000.","In C2 type =B2/B6. Write the other shares yourself: each divides by B6.","★ Challenge: in C6 total the shares. Build a pie chart from A1:B5."],"notes":"Expected: B6 = 2000; C2 = 0.4, C3 = 0.2, C4 = 0.15, C5 = 0.25; C6 = 1 (100%). If the shares do not add up to 100% the pie does not close — look for the mistake."},"stage":"practice"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Диаграмма түрін таңда","prompt":"Апта ішіндегі температураның өзгеруін көрсету үшін қай диаграмма лайық?","options":["Сызықтық","Дөңгелек","Мүлде диаграмма керек емес","Дөңгелек немесе бағанды, бәрібір"],"answer":0,"explanation":"Өзгеру жылдамдығын (уақыт бойынша) сызықтық диаграмма жақсы көрсетеді.","points":1,"ru":{"title":"Выбери вид диаграммы","prompt":"Какая диаграмма лучше всего показывает изменение температуры за неделю?","options":["Линейная","Круговая","Диаграмма не нужна","Круговая или столбчатая, всё равно"],"explanation":"Изменение во времени лучше всего показывает линейная диаграмма."},"en":{"title":"Pick the chart","prompt":"Which chart shows how the temperature changed through the week?","options":["Line chart","Pie chart","No chart at all","Pie or bar, no difference"],"explanation":"Change over time is best shown by a line chart."},"stage":"check"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Дөңгелек диаграмма","prompt":"Шоколад құрамындағы бөліктерді (какао, қант, сүт) көрсету үшін қай диаграмма лайық?","options":["Дөңгелек — бөліктер бүтіннің үлесі","Сызықтық","Бағанды, себебі ол әрдайым дұрыс","Диаграмма керек емес"],"answer":0,"explanation":"Құрам — бүтіннің бөліктері, оны дөңгелек диаграмма жақсы көрсетеді.","points":1,"ru":{"title":"Круговая диаграмма","prompt":"Какая диаграмма лучше всего покажет составные части шоколада (какао, сахар, молоко)?","options":["Круговая — части составляют целое","Линейная","Столбчатая, она всегда подходит","Диаграмма не нужна"],"explanation":"Состав — это части целого, их хорошо показывает круговая диаграмма."},"en":{"title":"Pie chart","prompt":"Which chart best shows the ingredients of chocolate (cocoa, sugar, milk)?","options":["Pie — the parts make a whole","Line","Bar, it is always right","No chart needed"],"explanation":"A composition is parts of a whole, which a pie chart shows well."},"stage":"check"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Есеп: үлесі","prompt":"Дөңгелек диаграммада үш бөлік: 25%, 35% және ? Үшіншісі неше пайыз болуы керек?","accept":["40","40%"],"points":1,"ru":{"title":"Задача: доля","prompt":"На круговой диаграмме три части: 25%, 35% и ? Сколько процентов должна занимать третья?"},"en":{"title":"Problem: share","prompt":"A pie chart has three parts: 25%, 35% and ? What percent is the third?"},"stage":"check"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"check","title":"Қорытынды: бүгін не үйрендім?","bullets":["Бүгін мен … үйрендім (өз сөзіңмен жалғастыр).","Ең қызықты бөлігі: …","Маған әлі түсініксіз: …"],"ru":{"title":"Итог: что я узнал сегодня?","bullets":["Сегодня я научился … (продолжи своими словами).","Самое интересное: …","Мне пока непонятно: …"],"notes":"Ученики дописывают три предложения в тетрадь, 2–3 ученика читают вслух. Ответы «непонятно» разберите в начале следующего урока."},"en":{"title":"Wrap-up: what did I learn today?","bullets":["Today I learned … (finish in your own words).","The most interesting part: …","I still do not understand: …"],"notes":"Students finish three sentences in a notebook; 2–3 read aloud. Revisit the “do not understand” answers at the start of the next lesson."},"stage":"check","notes":"Оқушылар үш сөйлемді дәптерге жазады, 2–3 оқушы дауыстап оқиды. «Түсініксіз» жауаптарын келесі сабақтың басында қайталаңыз.","design":"lab"}]$s7$::jsonb),
    ($s7$3.7 Кестеде процестерді модельдеу$s7$, $s7$Информатика$s7$, 6, $s7${"summary":"IF функциясы шартқа қарай екі мәннің бірін береді; кіріктірілген IF; SUM, AVERAGE, COUNT, MIN, MAX функциялары.","objectives":["IF функциясының жазылуын түсіну: шарт, егер рас, егер жалған","Емтихан кестесінде «Pass/Fail» мәртебесін автоматты есептеу","SUM, AVERAGE, MIN, MAX функцияларымен деректерді талдау"],"grade":7,"duration":"45 минут","prior":"SUM, AVERAGE функцияларын, шартты пішімдеуді біледі (3.4–3.5 сабақтар).","env":"Кесте: ClassFlow кестесі немесе Google Sheets. Google Docs/Sheets үшін оқушыда Google аккаунты және интернет болуы керек (аккаунт мектеп ережесіне сай ашылады). Әр оқушыға бір құрылғы.","source":"A. Zhunussov, Ye. Shaniyev, I. Gesen. Informatics, Grade 7, 1st ed., Almaty, 2021, 38–39 беттер. Сабақтағы формулалар мен жауаптар кестеде орындалып тексерілген, деректер ойдан шығарылған.","stages":[{"k":"warmup","min":5,"do":"«Автоматты кесте ыңғайлы ма?» сұрағына жауап береді"},{"k":"together","min":8,"do":"IF функциясының жазылуын және мысалын үйренеді"},{"k":"example","min":10,"do":"Мұғаліммен бірге «Pass/Fail» мәртебесін IF-пен есептейді"},{"k":"practice","min":15,"do":"IF-пен мәртебе және функциялармен жалақы статистикасын есептейді"},{"k":"check","min":7,"do":"Қысқа тест тапсырып, не үйренгенін айтады"}],"ru":{"summary":"Функция IF выдаёт одно из двух значений по условию; вложенный IF; функции SUM, AVERAGE, COUNT, MIN, MAX.","objectives":["Понимать запись IF: условие, если истина, если ложь","Автоматически считать статус «Pass/Fail» в таблице экзаменов","Анализировать данные функциями SUM, AVERAGE, MIN, MAX"],"prior":"Знают функции SUM, AVERAGE и условное форматирование (уроки 3.4–3.5).","env":"Таблица: ClassFlow или Google Sheets. Для Google Docs/Sheets нужны аккаунт Google и интернет (аккаунт — по правилам школы). Каждому ученику по устройству.","source":"A. Zhunussov, Ye. Shaniyev, I. Gesen. Informatics, Grade 7, 1st ed., Almaty, 2021, с. 38–39. Формулы и ответы урока проверены выполнением в таблице, данные вымышленные.","stages":["Отвечает, удобна ли автоматическая таблица","Узнаёт запись IF и пример","Вместе с учителем считает «Pass/Fail» функцией IF","Считает статус через IF и статистику зарплат функциями","Проходит короткий тест и говорит, что узнал"]},"en":{"summary":"IF returns one of two values by a condition; nested IF; the functions SUM, AVERAGE, COUNT, MIN, MAX.","objectives":["Understand IF: condition, value if true, value if false","Work out a Pass/Fail status automatically in an exam table","Analyse data with SUM, AVERAGE, MIN and MAX"],"prior":"Know SUM, AVERAGE and conditional formatting (lessons 3.4–3.5).","env":"Spreadsheet: the ClassFlow sheet or Google Sheets. Google Docs/Sheets need a Google account and the internet (the account follows the school rules). One device per student.","source":"A. Zhunussov, Ye. Shaniyev, I. Gesen. Informatics, Grade 7, 1st ed., Almaty, 2021, pp. 38–39. The formulas and answers of the lesson were run in a sheet; the data are made up.","stages":["Answers whether an automatic table is more convenient","Learns how IF is written and sees an example","Calculates Pass/Fail with IF together with the teacher","Works out the status with IF and the salary statistics with functions","Takes a short test and says what was learned"]}}$s7$::jsonb, $s7$[{"term":"IF","definition":"IF(шарт; егер рас; егер жалған) — шартқа қарай екі мәннің бірін береді · IF(условие; если истина; если ложь) — возвращает одно из двух значений · IF(condition; if true; if false) — returns one of two values"},{"term":"logical expression","definition":"Логикалық өрнек — рас (TRUE) немесе жалған (FALSE) болатын салыстыру, мысалы A1>A2 · Логическое выражение — сравнение с результатом TRUE или FALSE, например A1>A2 · Logical expression — a comparison that is TRUE or FALSE, e.g. A1>A2"},{"term":"nested IF","definition":"Кіріктірілген IF — бірнеше шартты тексеру үшін IF ішіне IF жазу · Вложенный IF — IF внутри IF для проверки нескольких условий · Nested IF — one IF inside another to check several conditions"}]$s7$::jsonb, $s7$[{"type":"title","pageType":"slide","templateId":"title","title":"3.7 Кестеде процестерді модельдеу","subtitle":"Информатика 7-сынып · 3-тарау · оқулық 38–39-б.","ru":{"title":"3.7 Моделирование процессов в электронных таблицах","subtitle":"Информатика 7 класс · глава 3 · учебник, с. 38–39"},"en":{"title":"3.7 Modeling processes in spreadsheets","subtitle":"Informatics Grade 7 · Chapter 3 · textbook pp. 38–39"},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: функция","prompt":"A1:A4 ұяшықтарында 2, 4, 6, 8 сандары бар. =AVERAGE(A1:A4) нәтижесі қандай?","options":["5","20","4","8"],"answer":0,"explanation":"(2 + 4 + 6 + 8) / 4 = 20 / 4 = 5.","points":1,"ru":{"title":"Повторение: функция","prompt":"В A1:A4 числа 2, 4, 6, 8. Каков результат =AVERAGE(A1:A4)?","options":["5","20","4","8"],"explanation":"(2 + 4 + 6 + 8) / 4 = 20 / 4 = 5.","notes":"5 минут. Спросите: «Что удобнее — автоматическая таблица или заполнять вручную?» Ответы — подводка к IF."},"en":{"title":"Review: functions","prompt":"A1:A4 hold 2, 4, 6, 8. What does =AVERAGE(A1:A4) give?","options":["5","20","4","8"],"explanation":"(2 + 4 + 6 + 8) / 4 = 20 / 4 = 5.","notes":"5 minutes. Ask: “Which is handier — an automatic table or filling it in by hand?” It leads into IF."},"stage":"warmup","notes":"5 минут. Сұрақ: «Автоматты есептейтін кесте ыңғайлы ма, әлде қолмен толтыру ма?» Жауаптар IF-ке кіріспе."},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: салыстыру","prompt":"75 >= 75 өрнегінің нәтижесі қандай?","options":["TRUE (рас)","FALSE (жалған)","75","0"],"answer":0,"explanation":">= «үлкен немесе тең» дегенді білдіреді: 75 тең 75-ке, сондықтан рас.","points":1,"ru":{"title":"Повторение: сравнение","prompt":"Каков результат выражения 75 >= 75?","options":["TRUE (истина)","FALSE (ложь)","75","0"],"explanation":">= означает «больше или равно»: 75 равно 75, значит истина."},"en":{"title":"Review: comparison","prompt":"What is the result of 75 >= 75?","options":["TRUE","FALSE","75","0"],"explanation":">= means “greater than or equal”: 75 equals 75, so it is true."},"stage":"warmup"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"IF функциясы","bullets":["IF — шарт рас болса бір мәнді, жалған болса басқа мәнді қайтарады.","Жазылуы: =IF(шарт; егер рас; егер жалған). Мысалы: =IF(A1>A2; \"A1 үлкен\"; \"A2 үлкен\").","Мәтінді тырнақшаға аламыз. Шарт — салыстыру: >, <, >=, <=, =."],"art":"ifflow","ru":{"title":"Функция IF","bullets":["IF возвращает одно значение, если условие истинно, и другое, если ложно.","Запись: =IF(условие; если истина; если ложь). Например: =IF(A1>A2; \"A1 больше\"; \"A2 больше\").","Текст берём в кавычки. Условие — сравнение: >, <, >=, <=, =."]},"en":{"title":"The IF function","bullets":["IF returns one value if the condition is true and another if it is false.","Form: =IF(condition; if true; if false). For example: =IF(A1>A2; \"A1 is greater\"; \"A2 is greater\").","Text goes in quotes. The condition is a comparison: >, <, >=, <=, =."]},"stage":"together","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Кіріктірілген IF","bullets":["Бірнеше шартты тексеру үшін IF ішіне IF жазуға болады.","=IF(A1>85; \"5\"; IF(A1>65; \"4\"; \"3\")) — A1 85-тен үлкен болса 5; әйтпесе 65-тен үлкен болса 4; әйтпесе 3.","IF-ті қалағаныңша көп қолдануға болады, бірақ әр IF-тің жақшасын жабуды ұмытпа."],"code":"=IF(A1>85; \"5\"; IF(A1>65; \"4\"; \"3\"))","lang":"text","ru":{"title":"Вложенный IF","bullets":["Чтобы проверить несколько условий, один IF можно вложить в другой.","=IF(A1>85; \"5\"; IF(A1>65; \"4\"; \"3\")) — если A1 больше 85, то 5; иначе если больше 65, то 4; иначе 3.","IF можно вкладывать сколько нужно, но не забывай закрывать скобки каждого IF."],"notes":"8 минут. Объясните вложенный IF блок-схемой: если первое условие ложно, проверяется второе. При A1 = 70 результат 4, при A1 = 60 — 3."},"en":{"title":"Nested IF","bullets":["To check several conditions, put one IF inside another.","=IF(A1>85; \"5\"; IF(A1>65; \"4\"; \"3\")) — if A1 is above 85 write 5; else if above 65 write 4; else 3.","You can nest as many IFs as you need, but close the bracket of every IF."],"notes":"8 minutes. Explain nested IF with a flowchart: if the first condition is false the second is checked. A1 = 70 gives 4, A1 = 60 gives 3."},"stage":"together","notes":"8 минут. Кіріктірілген IF-ті блок-схемамен түсіндіріңіз: бірінші шарт жалған болса, екіншісі тексеріледі. A1 = 70 болса нәтиже 4, A1 = 60 болса 3.","design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Мысал: емтихан — Pass немесе Fail","bullets":["Орташа балл 75-тен кем болмаса, «Pass» жазылсын, әйтпесе «Fail».","D2 ұяшығына =IF(C2>=75; \"Pass\"; \"Fail\") жаз.","D2-нің оң жақ төменгі бұрышын төмен сүйре немесе екі рет шерт: формула қалған жолдарға көшеді."],"demoSheet":{"rows":5,"cols":4,"cells":{"A1":"Оқушы","B1":"Балл","C1":"Орташа","D1":"Мәртебе","A2":"Алмас","B2":"80, 70, 90","C2":"80","A3":"Айгерім","B3":"60, 70, 65","C3":"65","A4":"Нұрлан","B4":"90, 85, 80","C4":"85"},"fmt":{"A1":{"b":1,"bg":"#dbeafe"},"B1":{"b":1,"bg":"#dbeafe"},"C1":{"b":1,"bg":"#dbeafe"},"D1":{"b":1,"bg":"#dbeafe"}}},"notes":"10 минут. Күтілетін нәтиже: D2 = Pass (80), D3 = Fail (65), D4 = Pass (85). Шартты пішімдеумен Pass жолын жасыл, Fail жолын қызыл ет (3.5 сабақ). Жиі қате: тырнақшасыз Pass жазу, «;» орнына «.» қою.","ru":{"title":"Пример: экзамен — Pass или Fail","bullets":["Если средний балл не меньше 75, пишем «Pass», иначе «Fail».","В D2 запиши =IF(C2>=75; \"Pass\"; \"Fail\").","Протяни D2 за правый нижний угол вниз или щёлкни по нему дважды: формула скопируется в остальные строки."],"demoSheet":{"rows":5,"cols":4,"cells":{"A1":"Ученик","B1":"Баллы","C1":"Среднее","D1":"Статус","A2":"Алмас","B2":"80, 70, 90","C2":"80","A3":"Айгерим","B3":"60, 70, 65","C3":"65","A4":"Нурлан","B4":"90, 85, 80","C4":"85"},"fmt":{"A1":{"b":1,"bg":"#dbeafe"},"B1":{"b":1,"bg":"#dbeafe"},"C1":{"b":1,"bg":"#dbeafe"},"D1":{"b":1,"bg":"#dbeafe"}}},"notes":"10 минут. Ожидаемый результат: D2 = Pass (80), D3 = Fail (65), D4 = Pass (85). Условным форматированием закрасьте строки Pass зелёным, Fail красным (урок 3.5). Частые ошибки: Pass без кавычек, «.» вместо «;»."},"en":{"title":"Example: exam — Pass or Fail","bullets":["If the average is at least 75, write “Pass”, otherwise “Fail”.","In D2 type =IF(C2>=75; \"Pass\"; \"Fail\").","Drag D2 by its bottom-right corner or double-click it: the formula copies to the other rows."],"demoSheet":{"rows":5,"cols":4,"cells":{"A1":"Student","B1":"Scores","C1":"Average","D1":"Status","A2":"Almas","B2":"80, 70, 90","C2":"80","A3":"Aigerim","B3":"60, 70, 65","C3":"65","A4":"Nurlan","B4":"90, 85, 80","C4":"85"},"fmt":{"A1":{"b":1,"bg":"#dbeafe"},"B1":{"b":1,"bg":"#dbeafe"},"C1":{"b":1,"bg":"#dbeafe"},"D1":{"b":1,"bg":"#dbeafe"}}},"notes":"10 minutes. Expected: D2 = Pass (80), D3 = Fail (65), D4 = Pass (85). Use conditional formatting to colour Pass rows green and Fail rows red (lesson 3.5). Common slips: Pass without quotes, “.” instead of “;”."},"stage":"example"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Практика 1: емтихан мәртебесі","prompt":"Кестедегі сандарды енгіз. Орташа баллды AVERAGE-пен тап, ал мәртебені IF-пен есепте: орташа 75-тен кем болмаса — Pass, әйтпесе Fail.","points":10,"picture":"lec/inf8-g7-pass-kk.svg","pictureAlt":"Төрт оқушының үш пәннен баллы; орташа және мәртебе бағандары бос","sheet":{"rows":14,"cols":8},"criteria":[{"id":"c1","text":"Деректер енгізілген: B2 = 80 және D5 = 80","cell":"D5","points":1,"accept":["80"]},{"id":"c2","text":"E2 — Алмастың орташа баллы (AVERAGE)","cell":"E2","points":2,"fn":"AVERAGE","accept":["80"]},{"id":"c3","text":"E4 — Нұрланның орташа баллы","cell":"E4","points":1,"fn":"AVERAGE","accept":["85"]},{"id":"c4","text":"F2 — Алмастың мәртебесі (IF)","cell":"F2","points":2,"fn":"IF","accept":["Pass"]},{"id":"c5","text":"F3 — Айгерімнің мәртебесі: Fail","cell":"F3","points":2,"fn":"IF","accept":["Fail"]},{"id":"c6","text":"★ F5 — Дананың орташасы дәл 75: Pass","cell":"F5","points":2,"fn":"IF","accept":["Pass"]}],"steps":["Көмек: E2-ге =AVERAGE(B2:D2) жаз да, E5-ке дейін төмен тарт.","F2-ге =IF(E2>=75;\"Pass\";\"Fail\") жаз, мәтін тырнақшада. Қалған жолдарға көшір.","★ Күрделі: Дананың орташасы 75 — «>=» белгісі дұрыс жұмыс істей ме? «>» болса не болар еді?"],"notes":"Күтілетін нәтиже: орташалар 80, 65, 85, 75; мәртебелері Pass, Fail, Pass, Pass. Дана дәл 75 — «>=» оны Pass қылады; «>» қолданса Fail шығар еді. Көмек пен ★ деңгейі бар.","ru":{"title":"Практика 1: статус экзамена","prompt":"Введи числа из таблицы. Найди средний балл функцией AVERAGE, а статус посчитай через IF: если среднее не меньше 75 — Pass, иначе Fail.","picture":"lec/inf8-g7-pass-ru.svg","pictureAlt":"Баллы четырёх учеников по трём предметам; столбцы «среднее» и «статус» пустые","criteria":[{"id":"c1","text":"Данные введены: B2 = 80 и D5 = 80","cell":"D5","points":1},{"id":"c2","text":"E2 — средний балл Алмаса (AVERAGE)","cell":"E2","points":2,"fn":"AVERAGE"},{"id":"c3","text":"E4 — средний балл Нурлана","cell":"E4","points":1,"fn":"AVERAGE"},{"id":"c4","text":"F2 — статус Алмаса (IF)","cell":"F2","points":2,"fn":"IF"},{"id":"c5","text":"F3 — статус Айгерим: Fail","cell":"F3","points":2,"fn":"IF"},{"id":"c6","text":"★ F5 — у Даны среднее ровно 75: Pass","cell":"F5","points":2,"fn":"IF"}],"steps":["Подсказка: в E2 запиши =AVERAGE(B2:D2) и протяни до E5.","В F2 запиши =IF(E2>=75;\"Pass\";\"Fail\"), текст в кавычках. Скопируй в остальные строки.","★ Сложнее: у Даны среднее 75 — верно ли работает «>=»? Что было бы при «>»?"],"notes":"Ожидаемый результат: средние 80, 65, 85, 75; статусы Pass, Fail, Pass, Pass. У Даны ровно 75 — «>=» даёт Pass; при «>» вышло бы Fail. Есть подсказки и уровень ★."},"en":{"title":"Practice 1: exam status","prompt":"Enter the numbers from the table. Find the average with AVERAGE and work out the status with IF: Pass if the average is at least 75, otherwise Fail.","picture":"lec/inf8-g7-pass-en.svg","pictureAlt":"Scores of four students in three subjects; the average and status columns are empty","criteria":[{"id":"c1","text":"Data entered: B2 = 80 and D5 = 80","cell":"D5","points":1},{"id":"c2","text":"E2 — Almas’s average (AVERAGE)","cell":"E2","points":2,"fn":"AVERAGE"},{"id":"c3","text":"E4 — Nurlan’s average","cell":"E4","points":1,"fn":"AVERAGE"},{"id":"c4","text":"F2 — Almas’s status (IF)","cell":"F2","points":2,"fn":"IF"},{"id":"c5","text":"F3 — Aigerim’s status: Fail","cell":"F3","points":2,"fn":"IF"},{"id":"c6","text":"★ F5 — Dana’s average is exactly 75: Pass","cell":"F5","points":2,"fn":"IF"}],"steps":["Hint: in E2 type =AVERAGE(B2:D2) and drag down to E5.","In F2 type =IF(E2>=75;\"Pass\";\"Fail\"), text in quotes. Copy it to the other rows.","★ Challenge: Dana’s average is 75 — does “>=” work right? What would “>” give?"],"notes":"Expected: averages 80, 65, 85, 75; statuses Pass, Fail, Pass, Pass. Dana has exactly 75, so “>=” gives Pass; “>” would give Fail. There are hints and a ★ level."},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Практика 2: жалақы статистикасы","prompt":"Кестедегі жалақыны енгізіп, функциялармен орташа, ең көп, ең аз және жалпы жалақыны тап.","points":9,"picture":"lec/inf8-g7-salary-kk.svg","pictureAlt":"Бес қызметкердің жалақысы; орташа, ең көп, ең аз және жалпы бос","sheet":{"rows":14,"cols":8},"criteria":[{"id":"c1","text":"Деректер енгізілген: B2 = 250000 және B6 = 240000","cell":"B6","points":1,"accept":["240000"]},{"id":"c2","text":"B7 — орташа жалақы (AVERAGE)","cell":"B7","points":2,"fn":"AVERAGE","accept":["240000"]},{"id":"c3","text":"B8 — ең үлкен жалақы (MAX)","cell":"B8","points":2,"fn":"MAX","accept":["320000"]},{"id":"c4","text":"B9 — ең кіші жалақы (MIN)","cell":"B9","points":2,"fn":"MIN","accept":["180000"]},{"id":"c5","text":"B10 — жалпы жалақы (SUM)","cell":"B10","points":2,"fn":"SUM","accept":["1200000"]}],"steps":["Көмек: диапазон бәрінде B2:B6 (5 қызметкер).","B7 — AVERAGE, B8 — MAX, B9 — MIN, B10 — SUM."],"notes":"Күтілетін нәтиже: орташа 240000, ең көп 320000, ең аз 180000, жалпы 1200000. Жалақы — оқуға арналған ойдан шығарылған сандар.","ru":{"title":"Практика 2: статистика зарплат","prompt":"Введи зарплаты из таблицы и найди функциями среднюю, наибольшую, наименьшую и общую зарплату.","picture":"lec/inf8-g7-salary-ru.svg","pictureAlt":"Зарплаты пяти сотрудников; средняя, наибольшая, наименьшая и общая пустые","criteria":[{"id":"c1","text":"Данные введены: B2 = 250000 и B6 = 240000","cell":"B6","points":1},{"id":"c2","text":"B7 — средняя зарплата (AVERAGE)","cell":"B7","points":2,"fn":"AVERAGE"},{"id":"c3","text":"B8 — наибольшая зарплата (MAX)","cell":"B8","points":2,"fn":"MAX"},{"id":"c4","text":"B9 — наименьшая зарплата (MIN)","cell":"B9","points":2,"fn":"MIN"},{"id":"c5","text":"B10 — общая зарплата (SUM)","cell":"B10","points":2,"fn":"SUM"}],"steps":["Подсказка: диапазон везде B2:B6 (5 сотрудников).","B7 — AVERAGE, B8 — MAX, B9 — MIN, B10 — SUM."],"notes":"Ожидаемый результат: средняя 240000, наибольшая 320000, наименьшая 180000, общая 1200000. Зарплаты — придуманные учебные числа."},"en":{"title":"Practice 2: salary statistics","prompt":"Enter the salaries from the table and find the average, largest, smallest and total with functions.","picture":"lec/inf8-g7-salary-en.svg","pictureAlt":"Salaries of five employees; average, largest, smallest and total left empty","criteria":[{"id":"c1","text":"Data entered: B2 = 250000 and B6 = 240000","cell":"B6","points":1},{"id":"c2","text":"B7 — average salary (AVERAGE)","cell":"B7","points":2,"fn":"AVERAGE"},{"id":"c3","text":"B8 — largest salary (MAX)","cell":"B8","points":2,"fn":"MAX"},{"id":"c4","text":"B9 — smallest salary (MIN)","cell":"B9","points":2,"fn":"MIN"},{"id":"c5","text":"B10 — total salary (SUM)","cell":"B10","points":2,"fn":"SUM"}],"steps":["Hint: the range is B2:B6 everywhere (5 employees).","B7 uses AVERAGE, B8 MAX, B9 MIN, B10 SUM."],"notes":"Expected: average 240000, largest 320000, smallest 180000, total 1200000. The salaries are made-up classroom numbers."},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Есеп: кіріктірілген IF","prompt":"A1 = 70 болсын. =IF(A1>85; \"5\"; IF(A1>65; \"4\"; \"3\")) формуласы не көрсетеді? (бір сан)","accept":["4"],"points":2,"notes":"70 > 85 жалған; 70 > 65 рас → \"4\".","ru":{"title":"Задача: вложенный IF","prompt":"Пусть A1 = 70. Что покажет формула =IF(A1>85; \"5\"; IF(A1>65; \"4\"; \"3\"))? (одна цифра)","notes":"70 > 85 ложь; 70 > 65 истина → \"4\"."},"en":{"title":"Problem: nested IF","prompt":"Let A1 = 70. What does =IF(A1>85; \"5\"; IF(A1>65; \"4\"; \"3\")) show? (one digit)","notes":"70 > 85 is false; 70 > 65 is true → \"4\"."},"stage":"practice"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"IF жазылуы","prompt":"Рекордты тексеру: ұпай 97, бұрынғы рекорд 96. Қай формула «Жаңа рекорд» көрсетеді?","options":["=IF(97>96; \"New record\"; \"No\")","=SUM(97; 96)","=IF(\"New record\"; 97>96; \"No\")","=MAX(97>96)"],"answer":0,"explanation":"IF-тің бірінші аргументі — шарт (97>96), содан кейін «рас» және «жалған» мәндері.","points":1,"ru":{"title":"Запись IF","prompt":"Проверка рекорда: счёт 97, прежний рекорд 96. Какая формула покажет «Новый рекорд»?","options":["=IF(97>96; \"New record\"; \"No\")","=SUM(97; 96)","=IF(\"New record\"; 97>96; \"No\")","=MAX(97>96)"],"explanation":"Первый аргумент IF — условие (97>96), затем значения для «истина» и «ложь»."},"en":{"title":"Writing IF","prompt":"Checking a record: score 97, old record 96. Which formula shows “New record”?","options":["=IF(97>96; \"New record\"; \"No\")","=SUM(97; 96)","=IF(\"New record\"; 97>96; \"No\")","=MAX(97>96)"],"explanation":"The first argument of IF is the condition (97>96), then the true and false values."},"stage":"check"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Шарт орындалмаса","prompt":"=IF(A1>A2; \"A1 үлкен\"; \"A2 үлкен\") формуласында A1 = 5, A2 = 9. Нәтиже қандай?","options":["A2 үлкен","A1 үлкен","TRUE","Қате"],"answer":0,"explanation":"5 > 9 жалған, сондықтан үшінші аргумент көрсетіледі.","points":1,"ru":{"title":"Если условие не выполнено","prompt":"В =IF(A1>A2; \"A1 больше\"; \"A2 больше\") A1 = 5, A2 = 9. Каков результат?","options":["A2 больше","A1 больше","TRUE","Ошибка"],"explanation":"5 > 9 ложь, поэтому показывается третий аргумент."},"en":{"title":"When the condition fails","prompt":"In =IF(A1>A2; \"A1 is greater\"; \"A2 is greater\") A1 = 5 and A2 = 9. What is shown?","options":["A2 is greater","A1 is greater","TRUE","An error"],"explanation":"5 > 9 is false, so the third argument is shown."},"stage":"check"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"check","title":"Қорытынды: бүгін не үйрендім?","bullets":["Бүгін мен … үйрендім (өз сөзіңмен жалғастыр).","Ең қызықты бөлігі: …","Маған әлі түсініксіз: …"],"ru":{"title":"Итог: что я узнал сегодня?","bullets":["Сегодня я научился … (продолжи своими словами).","Самое интересное: …","Мне пока непонятно: …"],"notes":"Ученики дописывают три предложения в тетрадь, 2–3 ученика читают вслух. Ответы «непонятно» разберите в начале следующего урока."},"en":{"title":"Wrap-up: what did I learn today?","bullets":["Today I learned … (finish in your own words).","The most interesting part: …","I still do not understand: …"],"notes":"Students finish three sentences in a notebook; 2–3 read aloud. Revisit the “do not understand” answers at the start of the next lesson."},"stage":"check","notes":"Оқушылар үш сөйлемді дәптерге жазады, 2–3 оқушы дауыстап оқиды. «Түсініксіз» жауаптарын келесі сабақтың басында қайталаңыз.","design":"lab"}]$s7$::jsonb),
    ($s7$Өзіңді тексер: Электрондық кестелер$s7$, $s7$Информатика$s7$, 7, $s7${"summary":"3-тарауды қайталау: кесте, пішімдеу, деректер түрлері, формулалар мен функциялар, диаграммалар, IF.","objectives":["Тарау бойынша негізгі ұғымдарды еске түсіру","Бір кестеде формулаларды, функцияларды және IF-ті біріктіру","Өз білімін тестпен тексеру"],"grade":7,"duration":"45 минут","prior":"3.1–3.7 сабақтарының мазмұнын біледі.","env":"Кесте: ClassFlow кестесі немесе Google Sheets. Әр оқушыға бір құрылғы және интернет.","source":"A. Zhunussov, Ye. Shaniyev, I. Gesen. Informatics, Grade 7, 1st ed., Almaty, 2021, 40 беттер. Сабақтағы формулалар мен жауаптар кестеде орындалып тексерілген, деректер ойдан шығарылған.","stages":[{"k":"warmup","min":5,"do":"Тарау бойынша екі қайталау сұрағына жауап береді"},{"k":"together","min":8,"do":"Тараудың негізгі ұғымдарын кесте бойынша еске түсіреді"},{"k":"example","min":10,"do":"Мұғаліммен бірге оқушылар нәтижелері кестесінің шешімін талдайды"},{"k":"practice","min":15,"do":"Нәтижелер кестесін жеке жасайды: қосынды, пайыз, мәртебе, орташа"},{"k":"check","min":7,"do":"Оқулықтағы «Өзіңді тексер» сұрақтарынан тест тапсырады"}],"ru":{"summary":"Повторение главы 3: таблицы, форматирование, типы данных, формулы и функции, диаграммы, IF.","objectives":["Вспомнить основные понятия главы","Объединить в одной таблице формулы, функции и IF","Проверить себя тестом"],"prior":"Знают содержание уроков 3.1–3.7.","env":"Таблица: ClassFlow или Google Sheets. Каждому ученику по устройству и интернет.","source":"A. Zhunussov, Ye. Shaniyev, I. Gesen. Informatics, Grade 7, 1st ed., Almaty, 2021, с. 40. Формулы и ответы урока проверены выполнением в таблице, данные вымышленные.","stages":["Отвечает на два вопроса на повторение главы","Вспоминает основные понятия главы по сводке","Вместе с учителем разбирает решение таблицы результатов учеников","Самостоятельно делает таблицу результатов: сумма, процент, статус, среднее","Проходит тест по вопросам «Check yourself» учебника"]},"en":{"summary":"A review of chapter 3: tables, formatting, data types, formulas and functions, charts, IF.","objectives":["Recall the key ideas of the chapter","Combine formulas, functions and IF in one sheet","Test your own knowledge"],"prior":"Know the content of lessons 3.1–3.7.","env":"Spreadsheet: the ClassFlow sheet or Google Sheets. One device per student and the internet.","source":"A. Zhunussov, Ye. Shaniyev, I. Gesen. Informatics, Grade 7, 1st ed., Almaty, 2021, pp. 40. The formulas and answers of the lesson were run in a sheet; the data are made up.","stages":["Answers two review questions on the chapter","Recalls the key ideas of the chapter from a summary","Walks through the solution of a class results table with the teacher","Builds a results table alone: total, percent, status, average","Takes a test of the textbook’s “Check yourself” questions"]}}$s7$::jsonb, $s7$[{"term":"spreadsheet","definition":"Электрондық кесте — жолдар мен бағандардан тұратын электрондық кесте · Электронная таблица — таблица из строк и столбцов в электронном виде · Spreadsheet — an electronic table of rows and columns"},{"term":"formula","definition":"Формула — «=» таңбасынан басталатын өрнек · Формула — выражение, начинающееся с «=» · Formula — an expression starting with “=”"},{"term":"chart","definition":"Диаграмма — деректердің графиктік көрінісі · Диаграмма — графическое представление данных · Chart — a graphical representation of data"}]$s7$::jsonb, $s7$[{"type":"title","pageType":"slide","templateId":"title","title":"Өзіңді тексер: Электрондық кестелер","subtitle":"Информатика 7-сынып · 3-тарау · оқулық 40-б.","ru":{"title":"Проверь себя: Электронные таблицы","subtitle":"Информатика 7 класс · глава 3 · учебник, с. 40"},"en":{"title":"Check yourself: Spreadsheets","subtitle":"Informatics Grade 7 · Chapter 3 · textbook pp. 40"},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: бағдарлама","prompt":"Google Sheets қандай бағдарлама?","options":["Электрондық кесте","Мәтіндік редактор","Деректер қоры","Графикалық редактор"],"answer":0,"explanation":"Google Sheets — электрондық кесте; Google Docs — мәтіндік редактор.","points":1,"ru":{"title":"Повторение: программа","prompt":"Что за программа Google Sheets?","options":["Электронные таблицы","Текстовый редактор","База данных","Графический редактор"],"explanation":"Google Sheets — электронные таблицы; Google Docs — текстовый редактор.","notes":"5 минут. Вопросы взяты из раздела «Check yourself» учебника. Записывайте тех, кто ошибся, и вернитесь к теме в конце урока."},"en":{"title":"Review: program","prompt":"What kind of program is Google Sheets?","options":["Spreadsheet","Word processing","Database","Graphics"],"explanation":"Google Sheets is a spreadsheet; Google Docs is a word processor.","notes":"5 minutes. The questions come from the textbook’s “Check yourself”. Note who gets them wrong and return to the topic at the end."},"stage":"warmup","notes":"5 минут. Сұрақтар оқулықтың «Check yourself» бөлімінен алынған. Дұрыс жауап бермегендерді жазып алыңыз: сабақтың соңында қайталаймыз."},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: кесте не?","prompt":"Электрондық кесте неден тұрады?","options":["Жолдар мен бағандардан","Тек суреттерден","Тек бағандардан","Тек мәтіннен"],"answer":0,"explanation":"Кесте жолдар (көлденең) мен бағандардан (тік) тұрады, олардың қиылысы — ұяшық.","points":1,"ru":{"title":"Повторение: из чего таблица","prompt":"Из чего состоит электронная таблица?","options":["Из строк и столбцов","Только из рисунков","Только из столбцов","Только из текста"],"explanation":"Таблица состоит из строк (горизонтальных) и столбцов (вертикальных), их пересечение — ячейка."},"en":{"title":"Review: a spreadsheet is made of","prompt":"What does a spreadsheet consist of?","options":["Rows and columns","Pictures only","Columns only","Text only"],"explanation":"A sheet is made of rows (horizontal) and columns (vertical); their crossing is a cell."},"stage":"warmup"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"3-тараудың қысқаша мазмұны","bullets":["Кесте: Insert → Table; ұяшықты біріктіру, өлшемін өзгерту, қатыру. Пішім: туралау, қаріп, түс, шекара.","Деректер түрлері: Number, Percent, Currency, Date, Time, Plain text. Формула «=» таңбасынан басталады, функциялар: SUM, AVERAGE, COUNT, MIN, MAX.","Шартты пішімдеу — шартқа қарай түс. Диаграммалар: бағанды, сызықтық, дөңгелек. IF(шарт; рас; жалған)."],"ru":{"title":"Краткое содержание главы 3","bullets":["Таблица: Insert → Table; объединение, размер, закрепление ячеек. Формат: выравнивание, шрифт, цвет, границы.","Типы данных: Number, Percent, Currency, Date, Time, Plain text. Формула начинается с «=», функции: SUM, AVERAGE, COUNT, MIN, MAX.","Условное форматирование — цвет по условию. Диаграммы: столбчатая, линейная, круговая. IF(условие; истина; ложь)."],"notes":"8 минут. Прочитайте сводку с экрана и по каждой строке задайте вопрос: «какая диаграмма?», «какая функция?»."},"en":{"title":"Chapter 3 at a glance","bullets":["Tables: Insert → Table; merge, resize and freeze cells. Format: alignment, font, colour, borders.","Data types: Number, Percent, Currency, Date, Time, Plain text. A formula starts with “=”; functions: SUM, AVERAGE, COUNT, MIN, MAX.","Conditional formatting is colour by a condition. Charts: bar, line, pie. IF(condition; true; false)."],"notes":"8 minutes. Read the summary from the screen and ask one question per line: “which chart?”, “which function?”."},"stage":"together","notes":"8 минут. Қысқаша мазмұнды экраннан оқып, әр жолға бір сұрақ қойыңыз: «қай диаграмма?», «қай функция?».","design":"lab"},{"type":"solution","pageType":"slide","templateId":"worked-example","kind":"exampletask","title":"Мысал: сынып нәтижелері","sections":[{"h":"Шарты","text":"B2:C5 ұяшықтарында төрт оқушының екі тесттегі баллы (әрқайсысы 50-ден). D бағанында қосынды, E бағанында пайыз (қосынды / 100), F бағанында: 75%-дан кем болмаса Pass, әйтпесе Fail."},{"h":"Алгоритм (қадамдар)","bullets":["D2-ге =SUM(B2:C2) жаз, төмен тарт.","E2-ге =D2/100 жаз, Percent түрін қой.","F2-ге =IF(E2>=0.75;\"Pass\";\"Fail\") жаз, төмен тарт."]},{"h":"Шешімі","text":"Қосындылар 85, 55, 95, 75; пайыздар 85%, 55%, 95%, 75%; мәртебелер Pass, Fail, Pass, Pass.","hide":true}],"art":"ifflow","ru":{"title":"Пример: результаты класса","sections":[{"h":"Условие","text":"В B2:C5 баллы четырёх учеников за два теста (каждый из 50). В столбце D сумма, в E процент (сумма / 100), в F: Pass, если не меньше 75%, иначе Fail."},{"h":"Алгоритм (шаги)","bullets":["В D2 запиши =SUM(B2:C2) и протяни вниз.","В E2 запиши =D2/100, включи формат Percent.","В F2 запиши =IF(E2>=0.75;\"Pass\";\"Fail\") и протяни вниз."]},{"h":"Решение","text":"Суммы 85, 55, 95, 75; проценты 85%, 55%, 95%, 75%; статусы Pass, Fail, Pass, Pass.","hide":true}],"notes":"10 минут. Покажите по шагам. У Даурена ровно 75% — «>=» даёт Pass, здесь часто ошибаются."},"en":{"title":"Example: class results","sections":[{"h":"Task","text":"B2:C5 hold four students’ scores in two tests (each out of 50). Column D is the total, E the percent (total / 100), F says Pass if at least 75%, otherwise Fail."},{"h":"Steps","bullets":["In D2 type =SUM(B2:C2) and drag down.","In E2 type =D2/100 and apply Percent.","In F2 type =IF(E2>=0.75;\"Pass\";\"Fail\") and drag down."]},{"h":"Solution","text":"Totals 85, 55, 95, 75; percents 85%, 55%, 95%, 75%; statuses Pass, Fail, Pass, Pass.","hide":true}],"notes":"10 minutes. Show it step by step. Dauren has exactly 75% — “>=” gives Pass, and it is a common slip."},"stage":"example","notes":"10 минут. Жолма-жол көрсетіңіз. Дәурендегі дәл 75% — «>=» шарты оны Pass етеді, бұл жиі қате жасалатын жер.","design":"lab"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Қорытынды практика: нәтижелер кестесі","prompt":"Кестедегі баллдарды енгіз. D бағанында қосындыны, E бағанында пайызды (қосынды / 100), F бағанында мәртебені (75%-дан кем болмаса Pass) есепте. Ең жоғары қосындыны тап.","points":14,"picture":"lec/inf8-g7-final-kk.svg","pictureAlt":"Төрт оқушының екі тест баллы; қосынды, пайыз, мәртебе және ең жоғары қосынды бос","sheet":{"rows":14,"cols":8},"criteria":[{"id":"c1","text":"Деректер енгізілген: B2 = 40 және C5 = 40","cell":"C5","points":1,"accept":["40"]},{"id":"c2","text":"D2 — Асемнің қосындысы (SUM)","cell":"D2","points":2,"fn":"SUM","accept":["85"]},{"id":"c3","text":"D5 — Дәуреннің қосындысы","cell":"D5","points":1,"fn":"SUM","accept":["75"]},{"id":"c4","text":"E2 — Асемнің пайызы (0.85 немесе 85%)","cell":"E2","points":2,"formula":true,"accept":["0.85","85%","85"]},{"id":"c5","text":"F2 — Асемнің мәртебесі (IF)","cell":"F2","points":2,"fn":"IF","accept":["Pass"]},{"id":"c6","text":"F3 — Бекзаттың мәртебесі: Fail","cell":"F3","points":2,"fn":"IF","accept":["Fail"]},{"id":"c7","text":"★ F5 — Дәуренде дәл 75%: Pass","cell":"F5","points":2,"fn":"IF","accept":["Pass"]},{"id":"c8","text":"★ D6 — ең жоғары қосынды (MAX)","cell":"D6","points":2,"fn":"MAX","accept":["95"]}],"steps":["Көмек: D2-ге =SUM(B2:C2), E2-ге =D2/100 жаз да, D5 пен E5-ке дейін төмен тарт.","F2-ге =IF(E2>=0.75;\"Pass\";\"Fail\") жаз; мәтін тырнақшада.","★ Күрделі: D6-ға =MAX(D2:D5). Қосымша: шартты пішімдеумен Pass жолдарын жасыл, Fail жолдарын қызыл ет."],"notes":"Күтілетін нәтиже: қосындылар 85, 55, 95, 75; пайыздар 0.85, 0.55, 0.95, 0.75; мәртебелер Pass, Fail, Pass, Pass; D6 = 95. Шартты пішімдеу мен диаграмма автоматты тексерілмейді — қалауы бойынша экраннан қараңыз.","ru":{"title":"Итоговая практика: таблица результатов","prompt":"Введи баллы из таблицы. Посчитай в D сумму, в E процент (сумма / 100), в F статус (Pass, если не меньше 75%). Найди наибольшую сумму.","picture":"lec/inf8-g7-final-ru.svg","pictureAlt":"Баллы четырёх учеников за два теста; сумма, процент, статус и наибольшая сумма пустые","criteria":[{"id":"c1","text":"Данные введены: B2 = 40 и C5 = 40","cell":"C5","points":1},{"id":"c2","text":"D2 — сумма Асем (SUM)","cell":"D2","points":2,"fn":"SUM"},{"id":"c3","text":"D5 — сумма Даурена","cell":"D5","points":1,"fn":"SUM"},{"id":"c4","text":"E2 — процент Асем (0.85 или 85%)","cell":"E2","points":2,"formula":true},{"id":"c5","text":"F2 — статус Асем (IF)","cell":"F2","points":2,"fn":"IF"},{"id":"c6","text":"F3 — статус Бекзата: Fail","cell":"F3","points":2,"fn":"IF"},{"id":"c7","text":"★ F5 — у Даурена ровно 75%: Pass","cell":"F5","points":2,"fn":"IF"},{"id":"c8","text":"★ D6 — наибольшая сумма (MAX)","cell":"D6","points":2,"fn":"MAX"}],"steps":["Подсказка: в D2 запиши =SUM(B2:C2), в E2 — =D2/100 и протяни до D5 и E5.","В F2 запиши =IF(E2>=0.75;\"Pass\";\"Fail\"); текст в кавычках.","★ Сложнее: в D6 запиши =MAX(D2:D5). Дополнительно: условным форматированием окрась Pass зелёным, Fail красным."],"notes":"Ожидаемый результат: суммы 85, 55, 95, 75; проценты 0.85, 0.55, 0.95, 0.75; статусы Pass, Fail, Pass, Pass; D6 = 95. Условное форматирование и диаграмма автоматически не проверяются — по желанию смотрите на экране."},"en":{"title":"Final practice: results table","prompt":"Enter the scores from the table. Work out the total in D, the percent in E (total / 100) and the status in F (Pass if at least 75%). Find the largest total.","picture":"lec/inf8-g7-final-en.svg","pictureAlt":"Four students’ scores in two tests; total, percent, status and the largest total left empty","criteria":[{"id":"c1","text":"Data entered: B2 = 40 and C5 = 40","cell":"C5","points":1},{"id":"c2","text":"D2 — Asem’s total (SUM)","cell":"D2","points":2,"fn":"SUM"},{"id":"c3","text":"D5 — Dauren’s total","cell":"D5","points":1,"fn":"SUM"},{"id":"c4","text":"E2 — Asem’s percent (0.85 or 85%)","cell":"E2","points":2,"formula":true},{"id":"c5","text":"F2 — Asem’s status (IF)","cell":"F2","points":2,"fn":"IF"},{"id":"c6","text":"F3 — Bekzat’s status: Fail","cell":"F3","points":2,"fn":"IF"},{"id":"c7","text":"★ F5 — Dauren has exactly 75%: Pass","cell":"F5","points":2,"fn":"IF"},{"id":"c8","text":"★ D6 — the largest total (MAX)","cell":"D6","points":2,"fn":"MAX"}],"steps":["Hint: type =SUM(B2:C2) in D2 and =D2/100 in E2, then drag down to D5 and E5.","In F2 type =IF(E2>=0.75;\"Pass\";\"Fail\"); text in quotes.","★ Challenge: type =MAX(D2:D5) in D6. Extra: colour Pass rows green and Fail rows red with conditional formatting."],"notes":"Expected: totals 85, 55, 95, 75; percents 0.85, 0.55, 0.95, 0.75; statuses Pass, Fail, Pass, Pass; D6 = 95. Conditional formatting and charts are not auto-marked — check them on screen if you like."},"stage":"practice"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Пернетақта: қалың қаріп","prompt":"Мәтінді қалың (bold) ету үшін қай пернелер қолданылады?","options":["Ctrl + B","Ctrl + I","Ctrl + U","Ctrl + P"],"answer":0,"explanation":"Ctrl+B — қалың, Ctrl+I — көлбеу, Ctrl+U — асты сызылған.","points":1,"ru":{"title":"Горячие клавиши: полужирный","prompt":"Какие клавиши делают текст полужирным (bold)?","options":["Ctrl + B","Ctrl + I","Ctrl + U","Ctrl + P"],"explanation":"Ctrl+B — полужирный, Ctrl+I — курсив, Ctrl+U — подчёркнутый."},"en":{"title":"Shortcut: bold","prompt":"Which keys make text bold?","options":["Ctrl + B","Ctrl + I","Ctrl + U","Ctrl + P"],"explanation":"Ctrl+B is bold, Ctrl+I italic, Ctrl+U underlined."},"stage":"check"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Ұяшықта бірнеше жол","prompt":"Ұяшықта мәтінді бірнеше жолға жазу үшін қай құралды қолданамыз?","options":["Wrap text","Shrink to fit","Merge cells","Orientation"],"answer":0,"explanation":"Wrap text ұзын мәтінді ұяшықта жолдарға бөледі.","points":1,"ru":{"title":"Несколько строк в ячейке","prompt":"Какой инструмент переносит текст в ячейке на несколько строк?","options":["Wrap text","Shrink to fit","Merge cells","Orientation"],"explanation":"Wrap text переносит длинный текст по строкам внутри ячейки."},"en":{"title":"Several lines in a cell","prompt":"Which tool writes text over several lines in one cell?","options":["Wrap text","Shrink to fit","Merge cells","Orientation"],"explanation":"Wrap text breaks long text into lines inside a cell."},"stage":"check"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Функцияларды сәйкестендір","prompt":"Тізімдегі ең кіші санды табатын функция қайсы?","options":["MIN","MAX","SUM","AVERAGE"],"answer":0,"explanation":"MIN — ең кіші, MAX — ең үлкен, SUM — қосынды, AVERAGE — орташа.","points":1,"ru":{"title":"Сопоставь функции","prompt":"Какая функция находит наименьшее число в списке?","options":["MIN","MAX","SUM","AVERAGE"],"explanation":"MIN — наименьшее, MAX — наибольшее, SUM — сумма, AVERAGE — среднее."},"en":{"title":"Match the functions","prompt":"Which function finds the smallest number in a list?","options":["MIN","MAX","SUM","AVERAGE"],"explanation":"MIN is the smallest, MAX the largest, SUM the total, AVERAGE the mean."},"stage":"check"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Диаграмма түрі","prompt":"Бағанды диаграмма мен сызықтық диаграмма не үшін қолданылады?","options":["Бағанды — элементтерді салыстыру; сызықтық — өзгерісті көрсету","Бағанды — өзгерісті көрсету; сызықтық — құрамды көрсету","Екеуі де тек құрамды көрсетеді","Екеуі де тек мәтінді көрсетеді"],"answer":0,"explanation":"Бағанды диаграмма жеке мәндерді салыстырады, сызықтық диаграмма уақыт бойынша өзгерісті көрсетеді.","points":1,"ru":{"title":"Вид диаграммы","prompt":"Для чего используют столбчатую и линейную диаграммы?","options":["Столбчатая — сравнение элементов; линейная — показ изменений","Столбчатая — показ изменений; линейная — показ состава","Обе показывают только состав","Обе показывают только текст"],"explanation":"Столбчатая сравнивает отдельные значения, линейная показывает изменение во времени."},"en":{"title":"Chart type","prompt":"What are bar and line charts used for?","options":["Bar compares items; line shows change","Bar shows change; line shows composition","Both show composition only","Both show text only"],"explanation":"A bar chart compares single values, a line chart shows change over time."},"stage":"check"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Google Docs: кесте","prompt":"Google Docs-та кестені қай мәзір арқылы қоямыз?","options":["Insert → Table","File → Print","Tools → Spelling","View → Full screen"],"answer":0,"explanation":"Кестені Insert → Table арқылы қоямыз да, өлшемін торда таңдаймыз.","points":1,"ru":{"title":"Google Docs: таблица","prompt":"Через какое меню вставляют таблицу в Google Docs?","options":["Insert → Table","File → Print","Tools → Spelling","View → Full screen"],"explanation":"Таблицу вставляют через Insert → Table и выбирают размер на сетке."},"en":{"title":"Google Docs: table","prompt":"Which menu inserts a table in Google Docs?","options":["Insert → Table","File → Print","Tools → Spelling","View → Full screen"],"explanation":"Insert → Table, then pick the size on the grid."},"stage":"check"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"check","title":"Қорытынды: бүгін не үйрендім?","bullets":["Бүгін мен … үйрендім (өз сөзіңмен жалғастыр).","Ең қызықты бөлігі: …","Маған әлі түсініксіз: …"],"ru":{"title":"Итог: что я узнал сегодня?","bullets":["Сегодня я научился … (продолжи своими словами).","Самое интересное: …","Мне пока непонятно: …"],"notes":"Ученики дописывают три предложения в тетрадь, 2–3 ученика читают вслух. Ответы «непонятно» разберите в начале следующего урока."},"en":{"title":"Wrap-up: what did I learn today?","bullets":["Today I learned … (finish in your own words).","The most interesting part: …","I still do not understand: …"],"notes":"Students finish three sentences in a notebook; 2–3 read aloud. Revisit the “do not understand” answers at the start of the next lesson."},"stage":"check","notes":"Оқушылар үш сөйлемді дәптерге жазады, 2–3 оқушы дауыстап оқиды. «Түсініксіз» жауаптарын келесі сабақтың басында қайталаңыз.","design":"lab"}]$s7$::jsonb)
  ) as t(title, subject, position, plan, terms, slides)
  loop
    select cl.lesson_id into v_lesson from public.cf_curr_lessons cl where cl.module_id = v_module and cl.position = v_spec.position limit 1;
    if v_lesson is null then select id into v_lesson from public.cf_lessons where school_id = v_school and title = v_spec.title limit 1; end if;
    if v_lesson is null then
      insert into public.cf_lessons (school_id, owner_id, title, subject, plan, slides, terms)
      values (v_school, v_owner, v_spec.title, v_spec.subject, v_spec.plan, v_spec.slides, v_spec.terms) returning id into v_lesson;
    else
      update public.cf_lessons set title = v_spec.title, subject = v_spec.subject, plan = v_spec.plan, slides = v_spec.slides, terms = v_spec.terms, updated_at = now() where id = v_lesson;
    end if;
    insert into public.cf_curr_lessons (lesson_id, module_id, position) values (v_lesson, v_module, v_spec.position)
    on conflict (lesson_id) do update set module_id = excluded.module_id, position = excluded.position;
    v_lesson := null;
  end loop;
end;
$informatics7$;
